COPY public.exams_reading (id, title, slug, stream, level, body, translation_ru, tags, is_published, created_at, updated_at, translation_nb, translation_nn, translation_en, title_en, title_nb, title_nn, title_ru) FROM stdin;
192	En prat med sjefen	a1-bm-talk-with-boss	bokmaal	A1	Jeg heter Amir, og jeg vil snakke med sjefen om jobben min. Etter lunsj går jeg til kontoret hans og banker forsiktig på døren. Han sier «kom inn», og jeg setter meg på en stol. Jeg forklarer at jeg liker jobben, men at det noen dager er veldig travelt. Jeg spør om vi kan ha litt mer tid til å gjøre ferdig oppgavene våre. Sjefen lytter og nikker. Han sier at det er bra at jeg sier fra. Vi ser sammen på arbeidslista for uka og flytter noen oppgaver til en annen dag. Når jeg går ut fra kontoret, føler jeg meg lettet. Det var ikke så skummelt å snakke med sjefen som jeg trodde.	Меня зовут Амир, и я хочу поговорить с начальником о своей работе. После ланча я иду в его кабинет и аккуратно стучу в дверь. Он говорит «kom inn» («входите»), и я сажусь на стул. Я объясняю, что мне нравится работа, но что некоторые дни очень загруженные. Я спрашиваю, можем ли мы получить чуть больше времени, чтобы успевать заканчивать задачи. Начальник слушает и кивает. Он говорит, что хорошо, что я об этом говорю. Мы вместе смотрим рабочий список на неделю и переносим часть задач на другой день. Когда я выхожу из кабинета, мне становится легче. Разговаривать с начальником оказалось не так страшно, как я думал.	["A1", "work", "boss", "conversation", "tasks"]	t	2025-12-05 19:27:17.037689+00	2025-12-05 19:27:17.037707+00	Jeg heter Amir, og jeg vil snakke med sjefen om jobben min. Etter lunsj går jeg til kontoret hans og banker forsiktig på døren. Han sier «kom inn», og jeg setter meg på en stol. Jeg forklarer at jeg liker jobben, men at det noen dager er veldig travelt. Jeg spør om vi kan ha litt mer tid til å gjøre ferdig oppgavene våre. Sjefen lytter og nikker. Han sier at det er bra at jeg sier fra. Vi ser sammen på arbeidslista for uka og flytter noen oppgaver til en annen dag. Når jeg går ut fra kontoret, føler jeg meg lettet. Det var ikke så skummelt å snakke med sjefen som jeg trodde.	Eg heiter Amir, og eg vil snakke med sjefen om jobben min. Etter lunsj går eg til kontoret hans og bankar forsiktig på døra. Han seier «kom inn», og eg set meg på ein stol. Eg forklarer at eg liker jobben, men at det nokre dagar er veldig travelt. Eg spør om vi kan få litt meir tid til å gjere ferdig oppgåvene våre. Sjefen lyttar og nikkar. Han seier at det er bra at eg seier frå. Vi ser saman på arbeidslista for veka og flyttar nokre oppgåver til ein annan dag. Når eg går ut frå kontoret, kjenner eg meg letta. Det var ikkje så skummelt å snakke med sjefen som eg trudde.	My name is Amir, and I want to talk to my boss about my job. After lunch I go to his office and knock gently on the door. He says “come in”, and I sit down on a chair. I explain that I like the job, but that some days are very busy. I ask if we can have a little more time to finish our tasks. The boss listens and nods. He says that it is good that I say something. Together we look at the work list for the week and move some tasks to another day. When I leave the office, I feel relieved. It was not as scary to talk to the boss as I had thought.	A talk with the boss	En prat med sjefen	Ein prat med sjefen	Разговор с начальником
7	Evening walk in the city	a1-evening-walk	english	A1	In the evening I like to take a short walk near my home. I put on a warm jacket and comfortable shoes. First I walk past a small park where children play. Then I go down the street and look at the lights in the windows. Sometimes I listen to a podcast in Norwegian while I walk. After twenty minutes I walk back home and make a cup of tea.	Вечером я люблю делать небольшую прогулку рядом с домом. Я надеваю тёплую куртку и удобную обувь. Сначала я прохожу мимо небольшого парка, где играют дети. Потом иду по улице и смотрю на огни в окнах. Иногда во время прогулки я слушаю подкаст на норвежском языке. Через двадцать минут я возвращаюсь домой и делаю себе чашку чая.	["A1", "everyday", "walk"]	t	2025-12-01 21:09:11.996415+00	2025-12-02 11:19:17.483353+00	Om kvelden liker eg å ta ein kort tur nær heimen min. Eg tek på meg ei varm jakke og gode sko. Først går eg forbi ein liten park der barna leikar. Så går eg nedover gata og ser på lysa i vindauga. Av og til høyrer eg på ein podkast på norsk medan eg går. Etter tjue minutt går eg heim igjen og lagar meg ein kopp te.	Om kvelden liker jeg å gå en liten tur i nærheten av hjemmet. Jeg tar på meg en varm jakke og gode sko. Først går jeg forbi en liten park hvor barna leker. Deretter går jeg nedover gaten og ser på lysene i vinduene. Noen ganger hører jeg på en podcast på norsk mens jeg går. Etter tjue minutter går jeg hjem igjen og lager meg en kopp te.	In the evening I like to take a short walk near my home. I put on a warm jacket and comfortable shoes. First I walk past a small park where children play. Then I go down the street and look at the lights in the windows. Sometimes I listen to a podcast in Norwegian while I walk. After twenty minutes I walk back home and make a cup of tea.	Evening walk in the city			
11	Å jobbe på et sykehjem	b2-bm-nursing-home	bokmaal	B2	Jeg jobber som helsefagarbeider på et lite sykehjem, og hver vakt er annerledes enn den forrige. Når jeg kommer på jobb om morgenen, går jeg først innom rapportrommet, der nattevakten forteller om hvordan natten har vært for beboerne. Noen netter har vært rolige, men andre ganger har noen hatt smerter, vært urolige eller savnet familien sin ekstra mye. Etter rapporten fordeler vi arbeidsoppgavene, og jeg starter ofte dagen med å hjelpe to eller tre beboere med morgenstell, medisiner og frokost. Det tar tid å gjøre alt rolig og trygt, fordi mange av dem både hører og beveger seg dårlig, og de trenger at vi er tålmodige og til stede hele tiden. Når vi har litt ro mellom oppgavene, prøver jeg å sette meg ned ved bordet, holde en hånd, høre på en historie fra gamle dager eller bare sitte stille sammen noen minutter. Jeg merker at små ting, som å huske favorittkoppen til en beboer eller å finne riktig musikk på radioen, kan gjøre en stor forskjell i humøret deres. Samtidig er jobben krevende; det er mange tunge løft, mye dokumentasjon på PC, telefoner fra pårørende og stadig nye rutiner vi må lære. Noen dager går jeg hjem og føler meg sliten i både kropp og hode, men likevel tenker jeg at det vi gjør, faktisk betyr noe for mennesker som er avhengige av oss. Det som motiverer meg mest, er når en stille beboer plutselig smiler, eller når en familie sier at de er trygge på at mor eller far har det godt hos oss. Da kjenner jeg at jeg har valgt riktig yrke, selv om det ikke alltid er enkelt.	Я работаю помощником по уходу в небольшом доме престарелых, и каждая смена отличается от предыдущей. Когда я прихожу на работу утром, я сначала захожу в комнату для отчётов, где ночная смена рассказывает, как прошла ночь у жильцов. Иногда ночь бывает спокойной, но в другие разы кто‑то испытывал боли, был беспокоен или особенно сильно скучал по семье. После отчёта мы делим между собой задачи, и я часто начинаю день с того, что помогаю двум–трём жильцам с утренним туалетом, лекарствами и завтраком. На всё уходит время, если делать это спокойно и безопасно, потому что многие из них плохо слышат и с трудом двигаются, и им нужно, чтобы мы были терпеливыми и постоянно рядом. Когда между заданиями есть немного тишины, я стараюсь сесть за стол, взять кого‑то за руку, послушать историю из прошлой жизни или просто посидеть рядом несколько минут. Я замечаю, что такие мелочи, как любимая кружка жильца или правильно подобранная музыка по радио, могут сильно изменить их настроение. В то же время работа тяжёлая: много физических нагрузок, много документации за компьютером, звонки от родственников и постоянно новые инструкции, которые нужно запоминать. Иногда я прихожу домой и чувствую усталость и в теле, и в голове, но всё равно думаю, что то, что мы делаем, действительно важно для людей, которые от нас зависят. Больше всего меня мотивирует, когда молчаливый житель вдруг улыбается или когда семья говорит, что им спокойно, потому что их мама или папа у нас в надёжных руках. Тогда я чувствую, что выбрал(а) правильную профессию, хотя она и не всегда бывает лёгкой.	["B2", "health", "job", "care"]	t	2025-12-02 09:51:15.842385+00	2025-12-02 11:19:58.249393+00	Jeg jobber som helsefagarbeider på et lite sykehjem, og hver vakt er annerledes enn den forrige. Når jeg kommer på jobb om morgenen, går jeg først innom rapportrommet, der nattevakten forteller om hvordan natten har vært for beboerne. Noen netter har vært rolige, men andre ganger har noen hatt smerter, vært urolige eller savnet familien sin ekstra mye. Etter rapporten fordeler vi arbeidsoppgavene, og jeg starter ofte dagen med å hjelpe to eller tre beboere med morgenstell, medisiner og frokost. Det tar tid å gjøre alt rolig og trygt, fordi mange av dem både hører og beveger seg dårlig, og de trenger at vi er tålmodige og til stede hele tiden. Når vi har litt ro mellom oppgavene, prøver jeg å sette meg ned ved bordet, holde en hånd, høre på en historie fra gamle dager eller bare sitte stille sammen noen minutter. Jeg merker at små ting, som å huske favorittkoppen til en beboer eller å finne riktig musikk på radioen, kan gjøre en stor forskjell i humøret deres. Samtidig er jobben krevende; det er mange tunge løft, mye dokumentasjon på PC, telefoner fra pårørende og stadig nye rutiner vi må lære. Noen dager går jeg hjem og føler meg sliten i både kropp og hode, men likevel tenker jeg at det vi gjør, faktisk betyr noe for mennesker som er avhengige av oss. Det som motiverer meg mest, er når en stille beboer plutselig smiler, eller når en familie sier at de er trygge på at mor eller far har det godt hos oss. Da kjenner jeg at jeg har valgt riktig yrke, selv om det ikke alltid er enkelt.	Eg jobbar som helsefagarbeidar på ein liten sjukeheim, og kvar vakt er annleis enn den førre. Når eg kjem på jobb om morgonen, går eg først innom rapportrommet, der nattevakta fortel om korleis natta har vore for bebuarane. Nokre netter har vore rolege, men andre gongar har nokon hatt smerter, vore urolige eller sakna familien sin ekstra mykje. Etter rapporten fordeler vi arbeidsoppgåvene, og eg startar ofte dagen med å hjelpe to eller tre bebuarar med morgonstell, medisin og frukost. Det tek tid å gjere alt roleg og trygt, fordi mange av dei både høyrer og rører seg dårleg, og dei treng at vi er tolmodige og til stades heile tida. Når vi har litt ro mellom oppgåvene, prøver eg å setje meg ned ved bordet, halde ei hand, høyre på ei historie frå gamle dagar eller berre sitje stille saman nokre minutt. Eg merkar at små ting, som å hugse favorittkoppen til ein bebuar eller å finne rett musikk på radioen, kan gjere ein stor skilnad for humøret deira. Samstundes er jobben krevjande; det er mange tunge løft, mykje dokumentasjon på PC, telefonar frå pårørande og stadig nye rutinar vi må lære. Nokre dagar går eg heim og kjenner meg sliten i både kropp og hovud, men likevel tenkjer eg at det vi gjer, faktisk betyr noko for menneske som er avhengige av oss. Det som motiverer meg mest, er når ein stille bebuar plutseleg smiler, eller når ein familie seier at dei er trygge på at mor eller far har det godt hos oss. Då kjenner eg at eg har valt rett yrke, sjølv om det ikkje alltid er enkelt.	I work as a health care worker in a small nursing home, and every shift is different from the previous one. When I arrive at work in the morning, I first go into the report room, where the night shift tells us how the night has been for the residents. Some nights have been calm, but other times someone has been in pain, been restless or missed their family a lot. After the handover we divide the tasks, and I often start the day by helping two or three residents with their morning care, medicines and breakfast. It takes time to do everything calmly and safely, because many of them both hear and move poorly, and they need us to be patient and present all the time. When we have a bit of calm between tasks, I try to sit down at the table, hold a hand, listen to a story from the old days or just sit quietly together for a few minutes. I notice that small things, like remembering a resident’s favourite cup or finding the right music on the radio, can make a big difference to their mood. At the same time, the job is demanding; there are many heavy lifts, a lot of documentation on the computer, phone calls from relatives and constantly new routines we have to learn. Some days I go home feeling tired in both body and head, but still I think that what we do really means something for people who depend on us. What motivates me most is when a quiet resident suddenly smiles, or when a family says that they feel confident that their mother or father is well cared for with us. Then I feel that I have chosen the right profession, even if it is not always easy.		Å jobbe på et sykehjem		
15	Legetime som språktrening	b2-bm-doctor-visit	bokmaal	B2	Etter fleire legebesøk i Noreg har eg forstått at eit møte med helsevesenet handlar om mykje meir enn prøvesvar og reseptar. For meg, som framandspråkleg pasient, er konsultasjonen også ein liten språktest kvar gong. Før eg går til timen, les eg gjennom meldinga på Helsenorge, sjekkar kva legen har skrive i innkallinga, og noterer spørsmål eg vil stille. Eg prøver å vere konkret: kor lenge har eg hatt symptoma, kva gjer smertene verre, og kva har eg sjølv prøvd allereie. Samtidig veit eg at legen har tidspress, og at køen ute på venterommet blir lengre for kvart ekstra minutt eg brukar. Difor øver eg på å forklare kort, men presist. Når legen møter meg med augekontakt, stiller opne spørsmål og sjekkar om eg har forstått, kjenner eg meg respektert både som pasient og som språkbrukar. Då tør eg òg å seie ifrå dersom noko verkar uklart, eller dersom ein behandlingsplan kolliderer med kvardagen min. Slik blir legetimen ein stad der eg ikkje berre får hjelp med kroppen, men også sakte bygger opp tillit – til systemet, til språket og til meg sjølv.	После нескольких приёмов у врача в Норвегии я понял, что встреча с системой здравоохранения — это гораздо больше, чем анализы и рецепты. Для меня, пациента с другим родным языком, консультация — это ещё и небольшой языковой тест каждый раз. Перед визитом я читаю сообщение на Helsenorge, проверяю, что врач написал в приглашении, и записываю вопросы, которые хочу задать. Я стараюсь быть конкретным: как долго у меня есть симптомы, что усиливает боль и что я уже пробовал делать сам. В то же время я понимаю, что у врача мало времени и что очередь в коридоре становится длиннее с каждой лишней минутой. Поэтому я тренируюсь объяснять коротко, но точно. Когда врач смотрит мне в глаза, задаёт открытые вопросы и проверяет, всё ли я понял, я чувствую уважение и как пациент, и как человек, говорящий на другом языке. Тогда я тоже осмеливаюсь сказать, если что‑то непонятно или если план лечения не подходит к моей повседневной жизни. Так приём у врача становится местом, где я не только получаю помощь для тела, но и постепенно строю доверие — к системе, к языку и к самому себе.	["B2", "health", "doctor", "communication"]	t	2025-12-03 08:13:17.999864+00	2025-12-03 08:13:17.999878+00	Etter fleire legebesøk i Noreg har eg forstått at eit møte med helsevesenet handlar om mykje meir enn prøvesvar og reseptar. For meg, som framandspråkleg pasient, er konsultasjonen også ein liten språktest kvar gong. Før eg går til timen, les eg gjennom meldinga på Helsenorge, sjekkar kva legen har skrive i innkallinga, og noterer spørsmål eg vil stille. Eg prøver å vere konkret: kor lenge har eg hatt symptoma, kva gjer smertene verre, og kva har eg sjølv prøvd allereie. Samtidig veit eg at legen har tidspress, og at køen ute på venterommet blir lengre for kvart ekstra minutt eg brukar. Difor øver eg på å forklare kort, men presist. Når legen møter meg med augekontakt, stiller opne spørsmål og sjekkar om eg har forstått, kjenner eg meg respektert både som pasient og som språkbrukar. Då tør eg òg å seie ifrå dersom noko verkar uklart, eller dersom ein behandlingsplan kolliderer med kvardagen min. Slik blir legetimen ein stad der eg ikkje berre får hjelp med kroppen, men også sakte bygger opp tillit – til systemet, til språket og til meg sjølv.	Etter fleire legebesøk i Noreg har eg forstått at eit møte med helsevesenet handlar om mykje meir enn prøvesvar og reseptar. For meg, som pasient med eit anna morsmål, er konsultasjonen òg ein liten språktest kvar gong. Før eg går til timen, les eg gjennom meldinga på Helsenorge, sjekkar kva legen har skrive i innkallinga, og noterer spørsmål eg vil stille. Eg prøver å vere konkret: kor lenge eg har hatt symptoma, kva som gjer smertene verre, og kva eg allereie har prøvd sjølv. Samstundes veit eg at legen har tidspress, og at køen ute på venterommet blir lengre for kvart ekstra minutt eg brukar. Difor øver eg på å forklare kort, men presist. Når legen møter meg med augekontakt, stiller opne spørsmål og sjekkar om eg har forstått, kjenner eg meg respektert både som pasient og som språkbrukar. Då tør eg òg å seie ifrå dersom noko verkar uklart, eller dersom ein behandlingsplan kolliderer med kvardagen min. Slik blir legetimen ein stad der eg ikkje berre får hjelp med kroppen, men òg sakte byggjer opp tillit – til systemet, til språket og til meg sjølv.	After several doctor’s visits in Norway, I have realised that a meeting with the health services is about much more than test results and prescriptions. For me, as a patient with another first language, the consultation is also a small language test every time. Before I go to the appointment, I read the message on Helsenorge, check what the doctor has written in the invitation, and write down the questions I want to ask. I try to be concrete: how long I have had the symptoms, what makes the pain worse, and what I have already tried myself. At the same time, I know that the doctor is under time pressure, and that the queue in the waiting room grows longer for every extra minute I use. Therefore I practise explaining things briefly, but precisely. When the doctor meets me with eye contact, asks open questions and checks that I have understood, I feel respected both as a patient and as a language user. Then I also dare to say if something is unclear, or if a treatment plan collides with my everyday life. In this way the doctor’s appointment becomes a place where I not only get help with my body, but also slowly build trust – in the system, in the language and in myself.				
20	På jobb på lageret	a1-bm-at-work	bokmaal	A1	Jeg heter Luis, og jeg jobber på et lite lager. Hver morgen kommer jeg på jobb klokka sju. Først tar jeg på meg refleksvest og vernesko. Så hilser jeg på kollegaene mine og sier «god morgen». Sjefen vår har et kort møte med oss. Han forteller hva vi skal gjøre i dag. Noen skal ta imot varer, andre skal pakke esker. I dag skal jeg kjøre truck og sette paller på plass. Jeg liker jobben min. Det er mye å gjøre, men vi hjelper hverandre, og dagen går fort.	Меня зовут Луис, и я работаю на небольшом складе. Каждое утро я прихожу на работу в семь часов. Сначала я надеваю светоотражающий жилет и защитную обувь. Потом я здороваюсь с коллегами и говорю «god morgen». Наш начальник проводит с нами короткое собрание. Он рассказывает, что мы будем делать сегодня. Кто-то будет принимать товары, другие — упаковывать коробки. Сегодня я буду водить погрузчик и ставить палеты на место. Я люблю свою работу. Дел много, но мы помогаем друг другу, и день проходит быстро.	["A1", "work", "job", "warehouse", "daily"]	t	2025-12-03 14:44:04.010427+00	2025-12-03 14:44:04.010444+00	Jeg heter Luis, og jeg jobber på et lite lager. Hver morgen kommer jeg på jobb klokka sju. Først tar jeg på meg refleksvest og vernesko. Så hilser jeg på kollegaene mine og sier «god morgen». Sjefen vår har et kort møte med oss. Han forteller hva vi skal gjøre i dag. Noen skal ta imot varer, andre skal pakke esker. I dag skal jeg kjøre truck og sette paller på plass. Jeg liker jobben min. Det er mye å gjøre, men vi hjelper hverandre, og dagen går fort.	Eg heiter Luis, og eg jobbar på eit lite lager. Kvar morgon kjem eg på jobb klokka sju. Først tek eg på meg refleksvest og vernesko. Så helsar eg på kollegaene mine og seier «god morgon». Sjefen vår har eit kort møte med oss. Han fortel kva vi skal gjere i dag. Nokre skal ta imot varer, andre skal pakke esker. I dag skal eg køyre truck og setje pallar på plass. Eg liker jobben min. Det er mykje å gjere, men vi hjelper kvarandre, og dagen går fort.	My name is Luis, and I work in a small warehouse. Every morning I arrive at work at seven o’clock. First I put on a reflective vest and safety shoes. Then I greet my colleagues and say “good morning”. Our boss has a short meeting with us. He tells us what we are going to do today. Some will receive goods, others will pack boxes. Today I am going to drive a truck and put pallets in place. I like my job. There is a lot to do, but we help each other and the day goes quickly.	At work in the warehouse	På jobb på lageret	På jobb på lageret	На работе на складе
193	Å snakke om arbeidstid	a2-bm-talk-with-boss	bokmaal	A2	Jeg har jobbet på samme avdeling i over ett år, og nå vil jeg snakke med lederen min om arbeidstid. Jeg liker kollegaene mine og selve jobben, men det er tungt å ha mange sene vakter etter hverandre. En dag etter jobb spør jeg om vi kan ta en kort prat. Vi går inn på et lite møterom, og jeg forklarer at familien min nesten aldri ser meg i ukedagene når jeg jobber kveldsvakt hele tiden. Lederen spør hvordan jeg ser for meg en bedre turnus. Jeg foreslår at jeg kan ta noen flere dagvakter og litt færre kvelder, og at jeg kan være fleksibel i helgene. Hun tar fram planen på skjermen og ser på fordelinga. Vi finner en løsning som fungerer både for avdelinga og for meg. Jeg går hjem med følelsen av at jeg har blitt tatt på alvor, og at det er mulig å snakke om slike ting før man blir helt utslitt.	Я работаю в одном и том же отделе уже больше года и сейчас хочу поговорить с руководительницей о рабочем времени. Мне нравятся коллеги и сама работа, но тяжело, когда несколько вечерних смен подряд. Однажды после работы я спрашиваю, можем ли мы немного поговорить. Мы заходим в маленькую переговорную, и я объясняю, что моя семья почти не видит меня в будни, когда я всё время работаю во вторую смену. Руководительница спрашивает, каким я вижу более удобный график. Я предлагаю взять немного больше дневных смен и чуть меньше вечерних, а по выходным быть гибким. Она открывает план на экране и смотрит, как всё распределено. Мы находим решение, которое подходит и отделу, и мне. Я иду домой с ощущением, что меня восприняли серьёзно и что о таких вещах можно говорить до того, как полностью выгоришь.	["A2", "work", "boss", "conversation", "shifts", "family"]	t	2025-12-05 19:27:17.045432+00	2025-12-05 19:27:17.04545+00	Jeg har jobbet på samme avdeling i over ett år, og nå vil jeg snakke med lederen min om arbeidstid. Jeg liker kollegaene mine og selve jobben, men det er tungt å ha mange sene vakter etter hverandre. En dag etter jobb spør jeg om vi kan ta en kort prat. Vi går inn på et lite møterom, og jeg forklarer at familien min nesten aldri ser meg i ukedagene når jeg jobber kveldsvakt hele tiden. Lederen spør hvordan jeg ser for meg en bedre turnus. Jeg foreslår at jeg kan ta noen flere dagvakter og litt færre kvelder, og at jeg kan være fleksibel i helgene. Hun tar fram planen på skjermen og ser på fordelinga. Vi finner en løsning som fungerer både for avdelinga og for meg. Jeg går hjem med følelsen av at jeg har blitt tatt på alvor, og at det er mulig å snakke om slike ting før man blir helt utslitt.	Eg har jobba på same avdeling i over eitt år, og no vil eg snakke med leiaren min om arbeidstid. Eg liker kollegaene mine og sjølve jobben, men det er tungt å ha mange seine vakter etter kvarandre. Ein dag etter jobb spør eg om vi kan ta ein kort prat. Vi går inn på eit lite møterom, og eg forklarer at familien min nesten aldri ser meg på vekedagar når eg har kveldsvakt heile tida. Leiaren spør korleis eg ser føre meg ein betre turnus. Eg foreslår at eg kan ta nokre fleire dagvakter og litt færre kveldar, og at eg kan vere fleksibel i helgene. Ho tek fram planen på skjermen og ser på fordelinga. Vi finn ei løysing som fungerer både for avdelinga og for meg. Eg går heim med ei kjensle av at eg har blitt tatt på alvor, og at det er mogleg å snakke om slike ting før ein blir heilt utsliten.	I have worked in the same department for over a year, and now I want to talk to my manager about working hours. I like my colleagues and the work itself, but it is hard to have many late shifts in a row. One day after work I ask if we can have a short talk. We go into a small meeting room, and I explain that my family almost never sees me on weekdays when I work evening shifts all the time. The manager asks how I imagine a better rota. I suggest that I can take some more day shifts and fewer evenings, and that I can be flexible at weekends. She opens the schedule on the screen and looks at the distribution. We find a solution that works both for the department and for me. I go home with the feeling that I have been taken seriously, and that it is possible to talk about such things before you are completely exhausted.	Talking about working hours	Å snakke om arbeidstid	Å snakke om arbeidstid	Разговор о рабочем времени
194	Mi første medarbeidersamtale	b1-bm-talk-with-boss	bokmaal	B1	Før eg kom til Noreg, hadde eg aldri høyrt om «medarbeidersamtale». Tanken på å sitje aleine med sjefen på eit lite kontor gjorde meg ganske nervøs. Men då eg fekk innkalling til mi første samtale, bestemte eg meg for å bruke sjansen godt. Eg skreiv ned nokre punkt heime: kva eg synest går bra på jobb, kva eg vil lære meir om, og kva som er vanskeleg i kvardagen. Under samtalen spurde leiaren først korleis eg trivst. Eg fortalde at eg liker arbeidsoppgåvene, men at det framleis er krevjande å forstå alle beskjedane når det går fort på møter. Ho foreslo at eg kunne få referat skriftleg etter viktige møte, og at vi kunne setje av litt tid til å gå gjennom nye rutinar på tomannshand. Samtidig gav ho meg ros for at eg tek ansvar når det oppstår problem på skiftet. Då eg gjekk ut av rommet, kjende eg at forholdet til sjefen hadde blitt tryggare. Eg forsto at slike samtalar ikkje berre handlar om kritikk, men om å finne gode løysingar saman.	До того как я приехал в Норвегию, я никогда не слышал о «medarbeidersamtale» — индивидуальной беседе сотрудника с руководителем. Мысль сидеть один на один с начальником в маленьком кабинете довольно сильно нервировала. Но когда я получил приглашение на такую встречу, решил использовать этот шанс. Дома я записал несколько пунктов: что, по моему мнению, хорошо получается на работе, чему я хотел бы научиться и что даётся трудно в повседневности. Во время беседы начальница сначала спросила, как я себя чувствую на работе. Я рассказал, что мне нравятся обязанности, но всё ещё тяжело понимать все сообщения, когда на совещаниях говорят очень быстро. Она предложила присылать мне краткие письменные резюме после важных встреч и выделять немного времени, чтобы мы могли вдвоём проходить новые процедуры. Заодно она похвалила меня за то, что я беру на себя ответственность, когда на смене возникают проблемы. Выходя из кабинета, я почувствовал, что мои отношения с начальством стали более доверительными. Я понял, что такие беседы — это не только про критику, но и про поиск общих решений.	["B1", "work", "boss", "employee-review", "feedback"]	t	2025-12-05 19:27:17.051682+00	2025-12-05 19:27:17.051702+00	Før eg kom til Noreg, hadde eg aldri høyrt om «medarbeidersamtale». Tanken på å sitje aleine med sjefen på eit lite kontor gjorde meg ganske nervøs. Men då eg fekk innkalling til mi første samtale, bestemte eg meg for å bruke sjansen godt. Eg skreiv ned nokre punkt heime: kva eg synest går bra på jobb, kva eg vil lære meir om, og kva som er vanskeleg i kvardagen. Under samtalen spurde leiaren først korleis eg trivst. Eg fortalde at eg liker arbeidsoppgåvene, men at det framleis er krevjande å forstå alle beskjedane når det går fort på møter. Ho foreslo at eg kunne få referat skriftleg etter viktige møte, og at vi kunne setje av litt tid til å gå gjennom nye rutinar på tomannshand. Samtidig gav ho meg ros for at eg tek ansvar når det oppstår problem på skiftet. Då eg gjekk ut av rommet, kjende eg at forholdet til sjefen hadde blitt tryggare. Eg forsto at slike samtalar ikkje berre handlar om kritikk, men om å finne gode løysingar saman.	Før eg kom til Noreg, hadde eg aldri høyrt om «medarbeidarsamtale». Tanken på å sitje åleine med sjefen på eit lite kontor gjorde meg ganske nervøs. Men då eg fekk innkalling til mi første samtale, bestemte eg meg for å bruke sjansen godt. Heime skreiv eg ned nokre punkt: kva eg synest går bra på jobb, kva eg vil lære meir om, og kva som er vanskeleg i kvardagen. Under samtalen spurde leiaren først korleis eg trivst. Eg fortalde at eg liker arbeidsoppgåvene, men at det framleis er krevjande å forstå alle beskjedane når det går fort på møte. Ho foreslo at eg kunne få referat skriftleg etter viktige møte, og at vi kunne setje av litt tid til å gå gjennom nye rutinar på tomannshand. Samstundes gav ho meg ros for at eg tek ansvar når det oppstår problem på skiftet. Då eg gjekk ut av rommet, kjende eg at forholdet til sjefen hadde blitt tryggare. Eg forsto at slike samtalar ikkje berre handlar om kritikk, men om å finne gode løysingar saman.	Before I came to Norway, I had never heard of an “employee review meeting”. The idea of sitting alone with the boss in a small office made me quite nervous. But when I received the invitation to my first meeting, I decided to use the opportunity well. At home I wrote down some points: what I think works well at work, what I want to learn more about, and what is difficult in everyday life. During the meeting the manager first asked how I was enjoying my job. I said that I like the tasks, but that it is still demanding to understand all the messages when things go fast in meetings. She suggested that I could get written summaries after important meetings, and that we could set aside some time to go through new routines one-to-one. At the same time she praised me for taking responsibility when problems arise on the shift. When I left the room, I felt that the relationship with my boss had become safer. I understood that such meetings are not only about criticism, but about finding good solutions together.	My first employee meeting	Min første medarbeidersamtale	Mi første medarbeidarsamtale	Моя первая medarbeidersamtale
195	Å ta opp vanskelige ting med sjefen	b2-bm-talk-with-boss	bokmaal	B2	Det tok tid før eg våga å ta opp vanskelege tema med leiaren min. I starten tenkte eg at ein «god arbeidstakar» berre seier ja, jobbar hardt og ikkje klagar. Etter nokre år erfarte eg at det kan bli farleg både for helsa og for arbeidsmiljøet å aldri seie frå. Ein vinter var bemanninga låg, sjukefråværet høgt og krava til produksjon dei same som før. Vi sprang mellom oppgåvene og gjorde så godt vi kunne, men likevel fekk vi beskjed om at vi måtte «stå på litt ekstra». Til slutt bad eg om ein samtale. Eg fortalde korleis kvardagen kjentes ut på skiftet, og at eg var redd for at fleire kom til å bli sjuke eller slutte dersom situasjonen heldt fram. Eg hadde også tenkt gjennom nokre konkrete forslag: justere bemanningsplanen, prioritere oppgåver og seie tydelegare nei til ekstraarbeid når det ikkje var forsvarleg. Leiaren blei stille ei stund, men takka for at eg sa frå så konkret. Nokre veker seinare såg vi at planen faktisk var endra. For meg blei det ei viktig erfaring: å ta opp problem med sjefen er ikkje det same som å vere «vanskelig». Det kan vere ein del av å ta ansvar – både for seg sjølv og for arbeidsplassen.	Мне понадобилось время, чтобы осмелиться поднимать сложные темы с руководством. Сначала я думал, что «хороший работник» — это тот, кто просто говорит «да», много работает и не жалуется. Через несколько лет я понял, что такое поведение может быть опасным и для здоровья, и для рабочего климата, если никогда не говорить о проблемах. Однажды зимой нас было мало, больничных было много, а требования по производству остались прежними. Мы бегали между задачами и делали всё, что могли, но нам всё равно говорили, что нужно «постараться ещё немного». В конце концов я попросил о встрече. Я рассказал, как на самом деле выглядит смена, и сказал, что боюсь: если так будет продолжаться, больше людей заболеют или уйдут. Я заранее продумал несколько конкретных предложений: подкорректировать план по числу сотрудников, расставить приоритеты по задачам и говорить более чёткое «нет» дополнительной работе, когда это уже небезопасно. Руководитель некоторое время молчал, а потом поблагодарил меня за то, что я так конкретно всё объяснил. Через несколько недель мы увидели, что план действительно изменили. Для меня это был важный опыт: поднимать проблемы с начальством — это не значит быть «трудным». Это может быть частью ответственности — и за себя, и за своё рабочее место.	["B2", "work", "boss", "communication", "responsibility", "work-environment"]	t	2025-12-05 19:27:17.058978+00	2025-12-05 19:27:17.059005+00	Det tok tid før eg våga å ta opp vanskelege tema med leiaren min. I starten tenkte eg at ein «god arbeidstakar» berre seier ja, jobbar hardt og ikkje klagar. Etter nokre år erfarte eg at det kan bli farleg både for helsa og for arbeidsmiljøet å aldri seie frå. Ein vinter var bemanninga låg, sjukefråværet høgt og krava til produksjon dei same som før. Vi sprang mellom oppgåvene og gjorde så godt vi kunne, men likevel fekk vi beskjed om at vi måtte «stå på litt ekstra». Til slutt bad eg om ein samtale. Eg fortalde korleis kvardagen kjentes ut på skiftet, og at eg var redd for at fleire kom til å bli sjuke eller slutte dersom situasjonen heldt fram. Eg hadde også tenkt gjennom nokre konkrete forslag: justere bemanningsplanen, prioritere oppgåver og seie tydelegare nei til ekstraarbeid når det ikkje var forsvarleg. Leiaren blei stille ei stund, men takka for at eg sa frå så konkret. Nokre veker seinare såg vi at planen faktisk var endra. For meg blei det ei viktig erfaring: å ta opp problem med sjefen er ikkje det same som å vere «vanskelig». Det kan vere ein del av å ta ansvar – både for seg sjølv og for arbeidsplassen.	Det tok tid før eg våga å ta opp vanskelege tema med leiaren min. I starten tenkte eg at ein «god arbeidstakar» berre seier ja, jobbar hardt og ikkje klagar. Etter nokre år erfarte eg at det kan vere farleg både for helsa og for arbeidsmiljøet å aldri seie frå. Ein vinter var bemanninga låg, sjukefråværet høgt og krava til produksjon dei same som før. Vi sprang mellom oppgåvene og gjorde så godt vi kunne, men likevel fekk vi beskjed om at vi måtte «stå på litt ekstra». Til slutt bad eg om ein samtale. Eg fortalde korleis kvardagen kjendes ut på skiftet, og at eg var redd for at fleire kom til å bli sjuke eller slutte dersom situasjonen heldt fram. Eg hadde òg tenkt gjennom nokre konkrete forslag: justere bemanningsplanen, prioritere oppgåver og seie tydelegare nei til ekstraarbeid når det ikkje var forsvarleg. Leiaren blei stille ei stund, men takka for at eg sa frå så konkret. Nokre veker seinare såg vi at planen faktisk var endra. For meg blei det ei viktig erfaring: å ta opp problem med sjefen er ikkje det same som å vere «vanskeleg». Det kan vere ein del av å ta ansvar – både for seg sjølv og for arbeidsplassen.	It took time before I dared to raise difficult topics with my manager. At the beginning I thought that a “good employee” just says yes, works hard and does not complain. After a few years I experienced that it can be dangerous both for health and for the working environment never to speak up. One winter the staffing level was low, sickness absence was high and the production demands were the same as before. We ran between tasks and did the best we could, but still we were told that we had to “push a bit extra”. Eventually I asked for a meeting. I explained what everyday life on the shift felt like, and that I was afraid more people would become ill or quit if the situation continued. I had also thought through some concrete suggestions: adjusting the staffing plan, prioritising tasks and saying more clearly no to extra work when it was not responsible. The manager was quiet for a while, but thanked me for speaking so concretely. A few weeks later we saw that the plan had actually been changed. For me this became an important experience: raising problems with the boss is not the same as being “difficult”. It can be part of taking responsibility – both for yourself and for the workplace.	Raising difficult issues with the boss	Å ta opp vanskelige ting med sjefen	Å ta opp vanskelege ting med sjefen	Как поднимать сложные темы с начальством
9	En helg hos besteforeldre	a2-bm-weekend-grandparents	bokmaal	A2	Jeg liker spesielt godt helgene når jeg besøker besteforeldrene mine på landet. Fredag ettermiddag tar jeg toget fra byen, og allerede på stasjonen kan jeg kjenne lukten av våt skog og frisk luft. Bestefar står og venter på meg med den gamle bilen sin, og han vinker stort når han ser meg. Hjemme hos dem lager bestemor varm suppe og nybakt brød, og vi sitter lenge ved kjøkkenbordet og snakker om alt som har skjedd siden sist. På lørdagen hjelper jeg bestefar i hagen; vi raker løv, bærer ved og gir mat til hønene deres. Etter arbeidet går vi en tur i skogen, og bestefar viser meg stier han gikk på da han var barn. Om kvelden spiller vi kort eller ser på en gammel film, mens vi drikker kakao og spiser småkaker. Når jeg reiser tilbake på søndag, er jeg ofte litt trøtt, men jeg føler meg rolig og glad, fordi helgen hos besteforeldrene gir meg masse energi.	Больше всего мне нравятся те выходные, когда я приезжаю к бабушке и дедушке в деревню. В пятницу после обеда я еду из города на поезде, и уже на вокзале чувствую запах мокрого леса и свежего воздуха. Дедушка ждёт меня со своей старой машиной и широко машет, когда видит меня. Дома у них бабушка готовит горячий суп и свежий хлеб, и мы долго сидим за кухонным столом и разговариваем обо всём, что случилось с прошлого раза. В субботу я помогаю дедушке в саду: мы сгребаем листья, носим дрова и кормим их кур. После работы мы идём гулять в лес, и дедушка показывает мне тропинки, по которым он ходил, когда был ребёнком. Вечером мы играем в карты или смотрим старый фильм, пока пьём какао и едим печенье. Когда в воскресенье я возвращаюсь домой, я часто немного уставший, но чувствую себя спокойным и счастливым, потому что выходные у бабушки и дедушки дают мне много энергии.	["A2", "family", "weekend", "travel"]	t	2025-12-02 09:51:15.828584+00	2025-12-02 11:19:29.163229+00	Jeg liker spesielt godt helgene når jeg besøker besteforeldrene mine på landet. Fredag ettermiddag tar jeg toget fra byen, og allerede på stasjonen kan jeg kjenne lukten av våt skog og frisk luft. Bestefar står og venter på meg med den gamle bilen sin, og han vinker stort når han ser meg. Hjemme hos dem lager bestemor varm suppe og nybakt brød, og vi sitter lenge ved kjøkkenbordet og snakker om alt som har skjedd siden sist. På lørdagen hjelper jeg bestefar i hagen; vi raker løv, bærer ved og gir mat til hønene deres. Etter arbeidet går vi en tur i skogen, og bestefar viser meg stier han gikk på da han var barn. Om kvelden spiller vi kort eller ser på en gammel film, mens vi drikker kakao og spiser småkaker. Når jeg reiser tilbake på søndag, er jeg ofte litt trøtt, men jeg føler meg rolig og glad, fordi helgen hos besteforeldrene gir meg masse energi.	Eg liker spesielt godt helgene når eg vitjar besteforeldra mine på landet. Fredag ettermiddag tek eg toget frå byen, og allereie på stasjonen kan eg kjenne lukta av våt skog og frisk luft. Bestefar står og ventar på meg med den gamle bilen sin, og han vinkar stort når han ser meg. Heime hos dei lagar bestemor varm suppe og nysteikt brød, og vi sit lenge ved kjøkenbordet og snakkar om alt som har skjedd sidan sist. På laurdag hjelper eg bestefar i hagen; vi raker lauv, ber ved og gir mat til hønene deira. Etter arbeidet går vi ein tur i skogen, og bestefar viser meg stiar han gjekk på då han var barn. Om kvelden spelar vi kort eller ser på ein gammal film, medan vi drikk kakao og et småkaker. Når eg reiser tilbake på sundag, er eg ofte litt trøytt, men eg kjenner meg roleg og glad, fordi helga hos besteforeldra gir meg masse energi.	I especially like the weekends when I visit my grandparents in the countryside. On Friday afternoon I take the train from the city, and already at the station I can smell the scent of the damp forest and the fresh air. Grandfather is waiting for me with his old car, and he waves big when he sees me. At their home, Grandmother makes hot soup and freshly baked bread, and we sit at the kitchen table for a long time and talk about everything that has happened since last time. On Saturday I help Grandfather in the garden; we rake leaves, carry firewood and feed their hens. After the work we go for a walk in the forest, and Grandfather shows me paths he used to walk when he was a child. In the evening we play cards or watch an old film while we drink cocoa and eat cookies. When I travel back on Sunday, I am often a bit tired, but I feel calm and happy, because the weekend at my grandparents’ gives me lots of energy.		En helg hos besteforeldre		
12	Hos fastlegen	a1-bm-doctor-visit	bokmaal	A1	Jeg heter Amir, og jeg bor i Norge sammen med familien min. I dag skal jeg til fastlegen. Jeg har hatt vondt i halsen i flere dager, og jeg er litt redd. På venterommet sitter det mange mennesker. Noen hoster, og et lite barn gråter stille. Jeg tar en lapp med nummer og setter meg ned. På veggen henger det bilder av kroppen og plakater om vaksiner. Etter en liten stund sier en dame i høyttaleren: «Nummer tjuefire til rom tre.» Det er min tur. Jeg går inn til legen, hilser og setter meg. Legen smiler og spør: «Hvordan går det med deg i dag?» Jeg kjenner at jeg blir roligere, og jeg begynner å forklare.	Меня зовут Амир, я живу в Норвегии вместе с семьёй. Сегодня я иду к семейному врачу. У меня несколько дней болело горло, и я немного боюсь. В комнате ожидания сидит много людей. Некоторые кашляют, маленький ребёнок тихо плачет. Я беру талон с номером и сажусь. На стене висят картинки с изображением тела и плакаты о прививках. Через некоторое время женщина говорит по громкой связи: «Номер двадцать четыре в кабинет три». Это моя очередь. Я захожу к врачу, здороваюсь и сажусь. Врач улыбается и спрашивает: «Как ты себя чувствуешь сегодня?» Я чувствую себя спокойнее и начинаю объяснять.	["A1", "health", "doctor", "visit"]	t	2025-12-03 08:13:17.977296+00	2025-12-03 08:13:17.977312+00	Jeg heter Amir, og jeg bor i Norge sammen med familien min. I dag skal jeg til fastlegen. Jeg har hatt vondt i halsen i flere dager, og jeg er litt redd. På venterommet sitter det mange mennesker. Noen hoster, og et lite barn gråter stille. Jeg tar en lapp med nummer og setter meg ned. På veggen henger det bilder av kroppen og plakater om vaksiner. Etter en liten stund sier en dame i høyttaleren: «Nummer tjuefire til rom tre.» Det er min tur. Jeg går inn til legen, hilser og setter meg. Legen smiler og spør: «Hvordan går det med deg i dag?» Jeg kjenner at jeg blir roligere, og jeg begynner å forklare.	Eg heiter Amir, og eg bur i Noreg saman med familien min. I dag skal eg til fastlegen. Eg har hatt vondt i halsen i fleire dagar, og eg er litt redd. På venterommet sit det mange menneske. Nokre hostar, og eit lite barn græt stille. Eg tek ein lapp med nummer og set meg ned. På veggen heng det bilete av kroppen og plakatar om vaksinar. Etter ei lita stund seier ei dame i høgtalaren: «Nummer tjuefire til rom tre.» Det er min tur. Eg går inn til legen, helsar og set meg. Legen smiler og spør: «Korleis går det med deg i dag?» Eg kjenner at eg blir rolegare, og eg begynner å forklare.	My name is Amir, and I live in Norway with my family. Today I am going to the general practitioner. I have had a sore throat for several days, and I am a little scared. In the waiting room there are many people. Some are coughing, and a small child is crying quietly. I take a ticket with a number and sit down. On the wall there are pictures of the body and posters about vaccines. After a little while a woman says on the loudspeaker: “Number twenty‑four to room three.” It is my turn. I go in to the doctor, say hello and sit down. The doctor smiles and asks, “How are you today?” I feel calmer, and I start to explain.				
13	Til legen aleine	a2-bm-doctor-visit	bokmaal	A2	Jeg kom til Norge for ett år siden og lærer fortsatt språket. I dag skal jeg til fastlegen alene for første gang. Før pleide kona mi å bli med og hjelpe meg med å forklare, men nå vil jeg prøve selv. Jeg har vondt i halsen og feber om kvelden, og jeg blir fort sliten på jobb. På venterommet leser jeg plakater om influensa og forkjølelse. Der står det at man må ringe legen hvis man har høy feber i flere dager. Jeg tenker at det var bra jeg bestilte time. Når nummeret mitt kommer opp på skjermen, banker jeg forsiktig på døren. Legen hilser, ser i datamaskinen og spør rolig: «Kan du fortelle litt om plagene dine?» Jeg snakker sakte, bruker enkle ord og hender når jeg ikke finner ordet. Legen lytter, smiler og sier at jeg forklarer veldig fint.	Я приехал в Норвегию год назад и всё ещё учу язык. Сегодня я иду к семейному врачу один впервые. Раньше жена ходила со мной и помогала объяснить, но сейчас я хочу попробовать сам. У меня болит горло и по вечерам поднимается температура, на работе я быстро устаю. В комнате ожидания я читаю плакаты о гриппе и простуде. Там написано, что нужно звонить врачу, если высокая температура держится несколько дней. Я думаю, что хорошо, что я записался на приём. Когда мой номер появляется на экране, я аккуратно стучу в дверь. Врач здоровается, смотрит в компьютер и спокойно спрашивает: «Можете немного рассказать о своих жалобах?» Я говорю медленно, использую простые слова и жесты, когда не нахожу нужного слова. Врач слушает, улыбается и говорит, что я очень хорошо всё объясняю.	["A2", "health", "doctor", "language"]	t	2025-12-03 08:13:17.983836+00	2025-12-03 08:13:17.983853+00	Jeg kom til Norge for ett år siden og lærer fortsatt språket. I dag skal jeg til fastlegen alene for første gang. Før pleide kona mi å bli med og hjelpe meg med å forklare, men nå vil jeg prøve selv. Jeg har vondt i halsen og feber om kvelden, og jeg blir fort sliten på jobb. På venterommet leser jeg plakater om influensa og forkjølelse. Der står det at man må ringe legen hvis man har høy feber i flere dager. Jeg tenker at det var bra jeg bestilte time. Når nummeret mitt kommer opp på skjermen, banker jeg forsiktig på døren. Legen hilser, ser i datamaskinen og spør rolig: «Kan du fortelle litt om plagene dine?» Jeg snakker sakte, bruker enkle ord og hender når jeg ikke finner ordet. Legen lytter, smiler og sier at jeg forklarer veldig fint.	Eg kom til Noreg for eitt år sidan og lærer framleis språket. I dag skal eg til fastlegen åleine for første gong. Før brukte kona mi å bli med og hjelpe meg å forklare, men no vil eg prøve sjølv. Eg har vondt i halsen og feber om kvelden, og eg blir fort sliten på jobb. På venterommet les eg plakatane om influensa og forkjøling. Der står det at ein må ringje legen dersom ein har høg feber i fleire dagar. Eg tenkjer at det var bra eg bestilte time. Når nummeret mitt kjem opp på skjermen, bankar eg forsiktig på døra. Legen helsar, ser i datamaskina og spør roleg: «Kan du fortelje litt om plagene dine?» Eg snakkar sakte, bruker enkle ord og hendene når eg ikkje finn ordet. Legen lyttar, smiler og seier at eg forklarer veldig fint.	I came to Norway one year ago and I am still learning the language. Today I am going to the general practitioner alone for the first time. Before, my wife used to come with me and help me explain, but now I want to try by myself. I have a sore throat and a fever in the evening, and I get tired quickly at work. In the waiting room I read posters about flu and colds. They say that you must call the doctor if you have a high fever for several days. I think it was good that I booked an appointment. When my number appears on the screen, I knock gently on the door. The doctor says hello, looks at the computer and asks calmly, “Can you tell me a little about your problems?” I speak slowly, use simple words and my hands when I cannot find the word. The doctor listens, smiles and says that I am explaining very well.				
8	En rolig morgen hjemme	a1-bm-morning-at-home	bokmaal	A1	Jeg heter Lena, og jeg bor i en liten leilighet sammen med familien min. Om morgenen våkner jeg klokka sju, men jeg står ikke opp med en gang, fordi jeg liker å ligge litt i senga og høre på regnet utenfor vinduet. Etter noen minutter går jeg på badet, pusser tennene, vasker ansiktet og grer håret. På kjøkkenet lager mamma brødskiver med ost og skinke, og jeg heller juice i glass til meg og lillebroren min. Vi sitter ved bordet, spiser frokost og snakker litt om dagen på skolen. Når klokka blir halv åtte, tar jeg på meg jakke og sko, setter sekken på ryggen og går til bussholdeplassen. Jeg liker denne rolige morgenen, fordi den hjelper meg å starte dagen på en god måte.	Меня зовут Лена, я живу в небольшой квартире вместе со своей семьёй. Утром я просыпаюсь в семь часов, но не встаю сразу, потому что люблю немного полежать в кровати и послушать дождь за окном. Через несколько минут я иду в ванную, чищу зубы, умываюсь и причёсываю волосы. На кухне мама делает бутерброды с сыром и ветчиной, а я наливаю сок в стаканы себе и младшему брату. Мы сидим за столом, завтракаем и немного разговариваем о школьном дне. Когда время подходит к половине восьмого, я надеваю куртку и обувь, беру рюкзак на спину и иду к автобусной остановке. Мне нравится такое спокойное утро, потому что оно помогает хорошо начать день.	["A1", "daily", "family", "morning"]	t	2025-12-02 09:51:15.820151+00	2025-12-02 11:19:08.790587+00	Jeg heter Lena, og jeg bor i en liten leilighet sammen med familien min. Om morgenen våkner jeg klokka sju, men jeg står ikke opp med en gang, fordi jeg liker å ligge litt i senga og høre på regnet utenfor vinduet. Etter noen minutter går jeg på badet, pusser tennene, vasker ansiktet og grer håret. På kjøkkenet lager mamma brødskiver med ost og skinke, og jeg heller juice i glass til meg og lillebroren min. Vi sitter ved bordet, spiser frokost og snakker litt om dagen på skolen. Når klokka blir halv åtte, tar jeg på meg jakke og sko, setter sekken på ryggen og går til bussholdeplassen. Jeg liker denne rolige morgenen, fordi den hjelper meg å starte dagen på en god måte.	Eg heiter Lena, og eg bur i ei lita leilegheit saman med familien min. Om morgonen vaknar eg klokka sju, men eg står ikkje opp med ein gong, fordi eg likar å liggje litt i senga og høyre på regnet utanfor vindauget. Etter nokre minutt går eg på badet, pussar tennene, vaskar ansiktet og greier håret. På kjøkenet lagar mamma brødskiver med ost og skinke, og eg heller jus i glas til meg og veslebroren min. Vi sit ved bordet, et frukost og snakkar litt om dagen på skulen. Når klokka blir halv åtte, tek eg på meg jakke og sko, set sekken på ryggen og går til busshaldeplassen. Eg likar denne rolege morgonen, fordi han hjelper meg å starte dagen på ein god måte.	My name is Lena, and I live in a small apartment with my family. In the morning I wake up at seven o’clock, but I don’t get up right away, because I like to lie in bed for a bit and listen to the rain outside the window. After a few minutes I go to the bathroom, brush my teeth, wash my face and comb my hair. In the kitchen, Mum makes slices of bread with cheese and ham, and I pour juice into glasses for myself and my little brother. We sit at the table, eat breakfast and talk a bit about the day at school. When it becomes half past seven, I put on my jacket and shoes, put my backpack on my back and walk to the bus stop. I like this quiet morning because it helps me start the day in a good way.		En rolig morgen hjemme		
10	Å begynne på en ny skole	b1-bm-new-school	bokmaal	B1	Da familien min flyttet til Norge, var jeg mest nervøs for å begynne på en ny skole. Jeg kunne litt norsk fra før, men jeg var redd for at jeg skulle bruke feil ord og at de andre skulle le av meg. Den første dagen fulgte læreren meg inn i klasserommet, presenterte meg for klassen og forklarte rolig at jeg var ny i landet. I friminuttet stod jeg først alene ved veggen, mens alle andre snakket fort og lo av vitser jeg ikke forsto. Plutselig kom ei jente bort til meg, smilte og spurte om jeg ville være med og spille fotball på banen. Jeg sa ja, selv om jeg egentlig ikke er så flink til å spille, fordi jeg tenkte at det var en god mulighet til å bli kjent med noen. Etter hvert som ukene gikk, begynte jeg å forstå mer av det lærerne sa, og jeg våget å rekke opp hånden i timene. Når jeg ikke forstår et ord, skriver jeg det i en liten notatbok, og hjemme slår jeg det opp i ordboka eller spør foreldrene mine. Nå føler jeg at skolen er et sted der jeg hører til, og jeg gleder meg til å møte vennene mine hver dag. Jeg er fortsatt ikke perfekt i norsk, men jeg ser at jeg blir litt bedre hver uke, og det gjør meg stolt.	Когда моя семья переехала в Норвегию, больше всего я переживал(а) из‑за того, что придётся идти в новую школу. Я уже немного знал(а) норвежский, но боялся(ась), что буду употреблять неправильные слова и что остальные будут надо мной смеяться. В первый день учитель зашёл со мной в класс, представил меня одноклассникам и спокойно объяснил, что я недавно приехал(а) в страну. На перемене я сначала стоял(а) один(одна) у стены, пока все остальные говорили быстро и смеялись над шутками, которых я не понимал(а). Вдруг ко мне подошла девочка, улыбнулась и спросила, не хочу ли я пойти с ними поиграть в футбол на поле. Я согласился(лась), хотя на самом деле не очень хорошо играю, потому что подумал(а), что это хороший шанс с кем‑то познакомиться. Со временем, когда проходили недели, я начал(а) больше понимать из того, что говорили учителя, и осмелился(лась) поднимать руку на уроках. Когда я не понимаю какое‑то слово, я записываю его в маленькую тетрадь, а дома ищу в словаре или спрашиваю у родителей. Теперь я чувствую, что школа – это место, где я на своём месте, и каждый день с радостью иду туда, чтобы увидеть своих друзей. Мой норвежский всё ещё далёк от идеала, но я вижу, что становлюсь понемногу лучше каждую неделю, и это делает меня гордым(ой).	["B1", "school", "integration"]	t	2025-12-02 09:51:15.837014+00	2025-12-02 11:19:44.001942+00	Da familien min flyttet til Norge, var jeg mest nervøs for å begynne på en ny skole. Jeg kunne litt norsk fra før, men jeg var redd for at jeg skulle bruke feil ord og at de andre skulle le av meg. Den første dagen fulgte læreren meg inn i klasserommet, presenterte meg for klassen og forklarte rolig at jeg var ny i landet. I friminuttet stod jeg først alene ved veggen, mens alle andre snakket fort og lo av vitser jeg ikke forsto. Plutselig kom ei jente bort til meg, smilte og spurte om jeg ville være med og spille fotball på banen. Jeg sa ja, selv om jeg egentlig ikke er så flink til å spille, fordi jeg tenkte at det var en god mulighet til å bli kjent med noen. Etter hvert som ukene gikk, begynte jeg å forstå mer av det lærerne sa, og jeg våget å rekke opp hånden i timene. Når jeg ikke forstår et ord, skriver jeg det i en liten notatbok, og hjemme slår jeg det opp i ordboka eller spør foreldrene mine. Nå føler jeg at skolen er et sted der jeg hører til, og jeg gleder meg til å møte vennene mine hver dag. Jeg er fortsatt ikke perfekt i norsk, men jeg ser at jeg blir litt bedre hver uke, og det gjør meg stolt.	Då familien min flytta til Noreg, var eg mest nervøs for å begynne på ein ny skule. Eg kunne litt norsk frå før, men eg var redd for at eg skulle bruke feil ord og at dei andre skulle le av meg. Den første dagen følgde læraren meg inn i klasserommet, presenterte meg for klassen og forklarte roleg at eg var ny i landet. I friminuttet stod eg først aleine ved veggen, medan alle andre snakka fort og lo av vitsar eg ikkje forstod. Plutseleg kom ei jente bort til meg, smilte og spurde om eg ville vere med og spele fotball på bana. Eg sa ja, sjølv om eg eigentleg ikkje er så flink til å spele, fordi eg tenkte at det var ei god moglegheit til å bli kjend med nokon. Etter kvart som vekene gjekk, byrja eg å forstå meir av det lærarane sa, og eg våga å rekke opp handa i timane. Når eg ikkje forstår eit ord, skriv eg det i ei lita notatbok, og heime slår eg det opp i ordboka eller spør foreldra mine. No kjenner eg at skulen er ein stad der eg høyrer til, og eg gler meg til å møte vennene mine kvar dag. Eg er framleis ikkje perfekt i norsk, men eg ser at eg blir litt betre kvar veke, og det gjer meg stolt.	When my family moved to Norway, I was most nervous about starting at a new school. I knew a little Norwegian from before, but I was afraid that I would use the wrong words and that the others would laugh at me. On the first day, the teacher walked with me into the classroom, introduced me to the class and calmly explained that I was new in the country. During recess I first stood alone by the wall, while everyone else talked fast and laughed at jokes I didn’t understand. Suddenly a girl came over to me, smiled and asked if I wanted to join in and play football on the field. I said yes, even though I’m actually not that good at playing, because I thought it was a good opportunity to get to know someone. As the weeks went by, I started to understand more of what the teachers said, and I dared to raise my hand in class. When I don’t understand a word, I write it down in a small notebook, and at home I look it up in the dictionary or ask my parents. Now I feel that school is a place where I belong, and I look forward to meeting my friends every day. I’m still not perfect in Norwegian, but I can see that I’m getting a little better every week, and that makes me proud.		Å begynne på en ny skole		
14	Å forklare smerte	b1-bm-doctor-visit	bokmaal	B1	Jeg har alltid syntes det var vanskelig å gå til legen, ikke bare på grunn av sykdom, men på grunn av språket. Før jeg kom til Norge, hadde jeg aldri tenkt på hvor viktig det er å kunne forklare smerte med riktige ord. Nå øver jeg ofte foran speilet før jeg skal til time. Jeg skriver ned nye ord, for eksempel «svie», «trykk» og «stikkende smerte», og prøver å bruke dem i setninger. Denne gangen fortalte jeg legen at halsen svir når jeg svelger, at jeg har feber om kvelden, og at jeg er redd for å smitte barna. Legen stilte mange oppfølgingsspørsmål, men snakket tydelig og litt saktere enn vanlig. Når jeg ikke forsto et ord, ba jeg henne gjenta eller forklare på en enklere måte. Etterpå kjente jeg meg stolt. Jeg gikk riktignok til legen fordi jeg var syk, men jeg gikk ut med følelsen av at språket mitt hadde blitt litt friskere.	Мне всегда было трудно ходить к врачу не только из‑за болезни, но и из‑за языка. До того как я приехал в Норвегию, я никогда не думал о том, как важно уметь описывать боль правильными словами. Теперь я часто тренируюсь перед зеркалом перед приёмом. Я записываю новые слова, например «жжение», «давление» и «колющая боль», и пытаюсь использовать их в предложениях. В этот раз я рассказал врачу, что горло жжёт, когда я глотаю, что вечером у меня температура и что я боюсь заразить детей. Врач задала много уточняющих вопросов, но говорила ясно и немного медленнее, чем обычно. Когда я не понимал какое‑то слово, я просил её повторить или объяснить проще. После этого я чувствовал гордость. Я пошёл к врачу, потому что был болен, но вышел с ощущением, что мой язык стал чуть-чуть здоровее.	["B1", "health", "doctor", "language"]	t	2025-12-03 08:13:17.99466+00	2025-12-03 08:15:33.434192+00	Jeg har alltid syntes det var vanskelig å gå til legen, ikke bare på grunn av sykdom, men på grunn av språket. Før jeg kom til Norge, hadde jeg aldri tenkt på hvor viktig det er å kunne forklare smerte med riktige ord. Nå