cting the children. The doctor asked many follow‑up questions, but spoke clearly and a little more slowly than usual. When I did not understand a word, I asked her to repeat or explain it in a simpler way. Afterwards I felt proud. I went to the doctor because I was ill, but I left with the feeling that my language had become a little healthier.	Explaining pain	Å forklare smerte	Å forklare smerte	Объяснить боль
16	På butikken	a1-bm-grocery-shopping	bokmaal	A1	Jeg heter Sara, og jeg skal på butikken etter jobb. Jeg har en liten handleliste i lomma. På lista står det melk, brød, egg, ost og epler. Utenfor butikken tar jeg en handlevogn. Det er mange mennesker inne, og det lukter ferskt brød. Jeg går først til frukten og legger seks røde epler i en pose. Så finner jeg melk i kjøleskapet og et enkelt brød uten frø. Til slutt går jeg til kassa. Kassadama sier «hei», og jeg svarer «hei». Jeg betaler med kort, får kvitteringen og sier «takk for i dag» før jeg går hjem.	Меня зовут Сара, и я иду в магазин после работы. У меня в кармане есть небольшой список покупок. В списке написано: молоко, хлеб, яйца, сыр и яблоки. Перед магазином я беру тележку. Внутри много людей, и пахнет свежим хлебом. Сначала я иду к фруктам и кладу в пакет шесть красных яблок. Потом нахожу молоко в холодильнике и простой хлеб без семян. В конце я подхожу к кассе. Кассир говорит «hei», и я отвечаю «hei». Я плачу картой, беру чек и говорю «takk for i dag», прежде чем пойти домой.	["A1", "daily", "shopping", "grocery"]	t	2025-12-03 09:15:51.596342+00	2025-12-03 09:15:51.596372+00	Jeg heter Sara, og jeg skal på butikken etter jobb. Jeg har en liten handleliste i lomma. På lista står det melk, brød, egg, ost og epler. Utenfor butikken tar jeg en handlevogn. Det er mange mennesker inne, og det lukter ferskt brød. Jeg går først til frukten og legger seks røde epler i en pose. Så finner jeg melk i kjøleskapet og et enkelt brød uten frø. Til slutt går jeg til kassa. Kassadama sier «hei», og jeg svarer «hei». Jeg betaler med kort, får kvitteringen og sier «takk for i dag» før jeg går hjem.	Eg heiter Sara, og eg skal på butikken etter jobb. Eg har ei lita handleliste i lomma. På lista står det mjølk, brød, egg, ost og eple. Utanfor butikken tek eg ein handlevogn. Det er mange menneske inne, og det luktar ferskt brød. Eg går først til frukta og legg seks raude eple i ein pose. Så finn eg mjølk i kjøleskapet og eit enkelt brød utan frø. Til slutt går eg til kassa. Kassadama seier «hei», og eg svarar «hei». Eg betaler med kort, får kvitteringa og seier «takk for i dag» før eg går heim.	My name is Sara, and I am going to the shop after work. I have a small shopping list in my pocket. On the list it says milk, bread, eggs, cheese and apples. Outside the shop I take a shopping trolley. There are many people inside, and it smells of fresh bread. First I go to the fruit and put six red apples in a bag. Then I find milk in the fridge and a simple bread without seeds. Finally I go to the checkout. The cashier says “hi”, and I answer “hi”. I pay by card, get the receipt and say “thanks for today” before I go home.	At the shop	På butikken	På butikken	В магазине
17	Handleliste og kassa	a2-bm-grocery-shopping	bokmaal	A2	Hver fredag etter jobb handler jeg for hele helgen. Jeg liker å være godt forberedt, så jeg skriver handleliste på mobilen før jeg drar. På lista står det ofte melk, kaffe, grønnsaker, frukt, ris og kylling. Når jeg kommer inn i butikken, ser jeg først på tilbudsplakatene ved inngangen. Hvis noe jeg trenger er på tilbud, blir jeg ekstra glad. I dag kjøper jeg gulrøtter, poteter og løk til middagssuppe. Jeg finner også yoghurt til barna og litt sjokolade til fredag kveld. Ved kassa legger jeg varene rolig på båndet og passer på at de tyngste varene kommer først. Når jeg har betalt, sjekker jeg om jeg har fått alle varene på kvitteringen. Det tar litt ekstra tid, men da vet jeg at alt stemmer før jeg går ut.	Каждую пятницу после работы я покупаю продукты на все выходные. Я люблю быть хорошо подготовленным, поэтому пишу список покупок в телефоне перед выходом. В списке часто есть молоко, кофе, овощи, фрукты, рис и курица. Когда я захожу в магазин, я сначала смотрю на плакаты с акциями у входа. Если что-то нужное мне по скидке, я особенно радуюсь. Сегодня я покупаю морковь, картошку и лук для супа на ужин. Я также беру йогурт для детей и немного шоколада на пятничный вечер. У кассы я спокойно выкладываю продукты на ленту и слежу, чтобы самые тяжёлые были первыми. Когда я заплатил, я проверяю, все ли товары есть в чеке. Это занимает немного больше времени, но так я знаю, что всё правильно, прежде чем выйти.	["A2", "daily", "shopping", "planning"]	t	2025-12-03 09:15:51.602442+00	2025-12-03 09:15:51.602453+00	Hver fredag etter jobb handler jeg for hele helgen. Jeg liker å være godt forberedt, så jeg skriver handleliste på mobilen før jeg drar. På lista står det ofte melk, kaffe, grønnsaker, frukt, ris og kylling. Når jeg kommer inn i butikken, ser jeg først på tilbudsplakatene ved inngangen. Hvis noe jeg trenger er på tilbud, blir jeg ekstra glad. I dag kjøper jeg gulrøtter, poteter og løk til middagssuppe. Jeg finner også yoghurt til barna og litt sjokolade til fredag kveld. Ved kassa legger jeg varene rolig på båndet og passer på at de tyngste varene kommer først. Når jeg har betalt, sjekker jeg om jeg har fått alle varene på kvitteringen. Det tar litt ekstra tid, men da vet jeg at alt stemmer før jeg går ut.	Kvar fredag etter jobb handlar eg for heile helga. Eg liker å vere godt førebudd, så eg skriv handleliste på mobilen før eg drar. På lista står det ofte mjølk, kaffe, grønsaker, frukt, ris og kylling. Når eg kjem inn i butikken, ser eg først på tilbodsplakatane ved inngangen. Dersom noko eg treng er på tilbod, blir eg ekstra glad. I dag kjøper eg gulrøter, poteter og lauk til middagssuppe. Eg finn òg yoghurt til barna og litt sjokolade til fredagskvelden. Ved kassa legg eg varene roleg på bandet og passar på at dei tyngste varene kjem først. Når eg har betalt, sjekkar eg om eg har fått alle varene på kvitteringa. Det tek litt ekstra tid, men då veit eg at alt stemmer før eg går ut.	Every Friday after work I shop for the whole weekend. I like to be well prepared, so I write a shopping list on my phone before I leave. On the list there is often milk, coffee, vegetables, fruit, rice and chicken. When I enter the shop, I first look at the special offer posters by the entrance. If something I need is on sale, I get especially happy. Today I buy carrots, potatoes and onions for a dinner soup. I also find yoghurt for the children and some chocolate for Friday evening. At the checkout I calmly put the goods on the belt and make sure that the heaviest items come first. When I have paid, I check whether I have got all the items on the receipt. It takes a little extra time, but then I know that everything is correct before I go out.	Shopping list and checkout	Handleliste og kassa	Handleliste og kassa	Список покупок и касса
18	Å handle sunnere	b1-bm-grocery-shopping	bokmaal	B1	Da jeg kom til Norge, syntes jeg det var vanskelig å handle i matbutikken. Jeg kjente ikke merkene, forsto ikke alle ordene på pakkene og brukte veldig lang tid i hver butikk. Ofte kjøpte jeg det som var billigst, uten å tenke så mye på hva jeg egentlig spiste. Etter hvert begynte jeg å lese små artikler om sunn mat på nett og på norsk. Jeg lærte ord som «grovt brød», «fullkorn», «tilsatt sukker» og «mettet fett». Nå ser jeg alltid på innholdslista før jeg legger noe i vogna. Jeg prøver å velge mer grønnsaker, frukt og grove produkter, og litt mindre brus og snacks. Det betyr ikke at jeg aldri kjøper noe godt, men at jeg planlegger det. Når jeg går ut av butikken med posene mine, føler jeg ikke bare at jeg har «handlet mat». Jeg føler også at jeg har tatt noen små, kloke valg for helsa mi.	Когда я приехал в Норвегию, мне было трудно покупать продукты в магазине. Я не знал марки, не понимал все слова на упаковках и проводил очень много времени в каждом магазине. Часто я покупал то, что было самым дешёвым, не думая о том, что именно я ем. Со временем я начал читать небольшие статьи о полезной еде в интернете и по-норвежски. Я выучил слова «grovt brød» (цельнозерновой хлеб), «fullkorn» (цельное зерно), «tilsatt sukker» (добавленный сахар) и «mettet fett» (насыщенные жиры). Теперь я всегда смотрю состав перед тем, как положить что-то в тележку. Я стараюсь выбирать больше овощей, фруктов и цельнозерновых продуктов и немного меньше газировки и снеков. Это не значит, что я никогда не покупаю что-то вкусное, но я планирую это. Когда я выхожу из магазина с пакетами, я чувствую не только, что «купил еду». Я чувствую, что сделал несколько маленьких, разумных шагов для своего здоровья.	["B1", "health", "shopping", "diet"]	t	2025-12-03 09:15:51.608183+00	2025-12-03 09:15:51.6082+00	Da jeg kom til Norge, syntes jeg det var vanskelig å handle i matbutikken. Jeg kjente ikke merkene, forsto ikke alle ordene på pakkene og brukte veldig lang tid i hver butikk. Ofte kjøpte jeg det som var billigst, uten å tenke så mye på hva jeg egentlig spiste. Etter hvert begynte jeg å lese små artikler om sunn mat på nett og på norsk. Jeg lærte ord som «grovt brød», «fullkorn», «tilsatt sukker» og «mettet fett». Nå ser jeg alltid på innholdslista før jeg legger noe i vogna. Jeg prøver å velge mer grønnsaker, frukt og grove produkter, og litt mindre brus og snacks. Det betyr ikke at jeg aldri kjøper noe godt, men at jeg planlegger det. Når jeg går ut av butikken med posene mine, føler jeg ikke bare at jeg har «handlet mat». Jeg føler også at jeg har tatt noen små, kloke valg for helsa mi.	Då eg kom til Noreg, syntest eg det var vanskeleg å handle i matbutikken. Eg kjende ikkje merka, forsto ikkje alle orda på pakkane og brukte veldig lang tid i kvar butikk. Ofte kjøpte eg det som var billigast, utan å tenkje så mykje på kva eg eigentleg åt. Etter kvart begynte eg å lese små artiklar om sunn mat på nett og på norsk. Eg lærte ord som «grovt brød», «fullkorn», «tilsett sukker» og «metta feitt». No ser eg alltid på innhaldslista før eg legg noko i vogna. Eg prøver å velje meir grønsaker, frukt og grove produkt, og litt mindre brus og snacks. Det betyr ikkje at eg aldri kjøper noko godt, men at eg planlegg det. Når eg går ut av butikken med posane mine, kjenner eg ikkje berre at eg har «handla mat». Eg kjenner òg at eg har tatt nokre små, kloke val for helsa mi.	When I came to Norway, I found it difficult to shop in the grocery store. I did not know the brands, I did not understand all the words on the packages, and I spent a very long time in every shop. Often I bought what was cheapest without thinking much about what I actually ate. After a while I started reading short articles about healthy food online and in Norwegian. I learnt words like “wholemeal bread”, “wholegrain”, “added sugar” and “saturated fat”. Now I always look at the list of ingredients before I put something in the trolley. I try to choose more vegetables, fruit and wholegrain products, and a little less soda and snacks. That does not mean that I never buy anything tasty, but that I plan it. When I leave the shop with my bags, I do not only feel that I have “bought food”. I also feel that I have made some small, wise choices for my health.	Shopping healthier	Å handle sunnere	Å handle sunnere	Покупать более полезную еду
21	Ein vanleg dag på jobb	a2-bm-at-work	bokmaal	A2	Jeg har jobb på et vaskeri som vasker sengetøy og klær for hoteller og sykehjem. Arbeidsdagen min starter klokka åtte. Før jeg begynner, drikker jeg en kopp kaffe sammen med to kollegaer i kantina. Vi snakker litt om været og om hvordan natta har vært. Når klokka blir åtte, går vi ned til maskinene. Jeg sorterer skittent tøy etter farge og temperatur. Noe skal vaskes på seksti grader, annet på førti. Etterpå legger jeg det våte tøyet inn i store tørketromler. Det er varmt og bråker mye i rommet, men vi har ørepropper og vifter. Midt på dagen har vi en halvtime pause. Da prøver jeg å legge fra meg mobilen og bare slappe av litt. Når jeg går hjem etter jobb, lukter klærne mine av såpe, og jeg er ofte trøtt, men også fornøyd fordi jeg vet at arbeidet mitt er viktig for mange mennesker.	Я работаю в прачечной, которая стирает постельное бельё и одежду для отелей и домов престарелых. Мой рабочий день начинается в восемь часов. Перед началом я пью чашку кофе с двумя коллегами в столовой. Мы немного говорим о погоде и о том, как прошла ночь. Когда наступает восемь, мы спускаемся к машинам. Я сортирую грязное бельё по цвету и температуре. Что‑то нужно стирать при шестидесяти градусах, что‑то при сорока. Потом я кладу мокрое бельё в большие сушильные машины. В комнате жарко и очень шумно, но у нас есть беруши и вентиляторы. В середине дня у нас полчаса перерыв. Тогда я стараюсь отложить телефон и просто немного отдохнуть. Когда я иду домой после работы, моя одежда пахнет мылом, и я часто уставший, но также доволен, потому что знаю: моя работа важна для многих людей.	["A2", "work", "job", "laundry", "routine"]	t	2025-12-03 14:44:04.018137+00	2025-12-03 14:44:04.018161+00	Jeg har jobb på et vaskeri som vasker sengetøy og klær for hoteller og sykehjem. Arbeidsdagen min starter klokka åtte. Før jeg begynner, drikker jeg en kopp kaffe sammen med to kollegaer i kantina. Vi snakker litt om været og om hvordan natta har vært. Når klokka blir åtte, går vi ned til maskinene. Jeg sorterer skittent tøy etter farge og temperatur. Noe skal vaskes på seksti grader, annet på førti. Etterpå legger jeg det våte tøyet inn i store tørketromler. Det er varmt og bråker mye i rommet, men vi har ørepropper og vifter. Midt på dagen har vi en halvtime pause. Da prøver jeg å legge fra meg mobilen og bare slappe av litt. Når jeg går hjem etter jobb, lukter klærne mine av såpe, og jeg er ofte trøtt, men også fornøyd fordi jeg vet at arbeidet mitt er viktig for mange mennesker.	Eg har jobb på eit vaskeri som vaskar sengetøy og klede for hotell og sjukeheimar. Arbeidsdagen min startar klokka åtte. Før eg begynner, drikk eg ein kopp kaffe saman med to kollegaer i kantina. Vi snakkar litt om vêret og om korleis natta har vore. Når klokka blir åtte, går vi ned til maskinene. Eg sorterer skittent tøy etter farge og temperatur. Noko skal vaskast på seksti grader, anna på førti. Etterpå legg eg det våte tøyet inn i store tørketromlar. Det er varmt og bråkar mykje i rommet, men vi har øyreproppar og vifter. Midt på dagen har vi ein pause på ein halvtime. Då prøver eg å leggje frå meg mobilen og berre slappe av litt. Når eg går heim etter jobb, luktar kleda mine av såpe, og eg er ofte trøytt, men òg fornøgd fordi eg veit at arbeidet mitt er viktig for mange menneske.	I work in a laundry that washes bed linen and clothes for hotels and nursing homes. My working day starts at eight o’clock. Before I begin, I drink a cup of coffee with two colleagues in the canteen. We talk a bit about the weather and about how the night has been. When the clock turns eight, we go down to the machines. I sort dirty clothes by colour and temperature. Some must be washed at sixty degrees, others at forty. Afterwards I put the wet laundry into large tumble dryers. It is hot and very noisy in the room, but we have earplugs and fans. In the middle of the day we have a half-hour break. Then I try to put away my phone and just relax a little. When I go home after work, my clothes smell of soap, and I am often tired, but also satisfied because I know that my work is important for many people.	A usual day at work	En vanlig dag på jobb	Ein vanleg dag på jobb	Обычный рабочий день
22	Nye kollegaer og språk	b1-bm-at-work	bokmaal	B1	Da jeg fikk min første jobb i Norge, var jeg mest nervøs for språket. Jeg visste at jeg kunne gjøre selve arbeidet, men jeg var redd for kaffepauser og småprat. På de første vaktene satt jeg ofte stille og bare lyttet. Jeg forsto kanskje halvparten av det kollegaene mine sa, og jeg brukte lang tid på å våge å stille spørsmål. Etter hvert begynte jeg å lære små uttrykk som «skal vi ta en pause?», «hvordan gikk det i går?» og «takk for hjelpa». Jeg oppdaget at de andre ikke forventet perfekt norsk, de var bare glade for at jeg prøvde. Nå er det ofte jeg som hjelper nye ansatte med å forstå beskjedene fra sjefen. Vi ler av misforståelser sammen, og jeg kjenner at jobb ikke bare handler om lønn og oppgaver, men også om å høre til i et fellesskap på arbeidsplassen.	Когда я получил свою первую работу в Норвегии, больше всего я переживал из‑за языка. Я знал, что могу выполнять саму работу, но боялся кофе-брейков и разговоров «ни о чём». В первые смены я часто сидел тихо и просто слушал. Я понимал, может быть, половину того, что говорили мои коллеги, и долго не решался задавать вопросы. Постепенно я выучил маленькие выражения вроде «skal vi ta en pause?» (может, сделаем перерыв?), «hvordan gikk det i går?» (как прошло вчера?) и «takk for hjelpa» (спасибо за помощь). Я увидел, что остальные не ждут идеального норвежского, они просто рады, что я стараюсь. Теперь часто уже я помогаю новым сотрудникам понимать сообщения от начальника. Мы вместе смеёмся над недопониманиями, и я чувствую, что работа — это не только зарплата и задачи, но и чувство, что ты принадлежишь коллективу на рабочем месте.	["B1", "work", "language", "colleagues", "integration"]	t	2025-12-03 14:44:04.025284+00	2025-12-03 14:44:04.025303+00	Da jeg fikk min første jobb i Norge, var jeg mest nervøs for språket. Jeg visste at jeg kunne gjøre selve arbeidet, men jeg var redd for kaffepauser og småprat. På de første vaktene satt jeg ofte stille og bare lyttet. Jeg forsto kanskje halvparten av det kollegaene mine sa, og jeg brukte lang tid på å våge å stille spørsmål. Etter hvert begynte jeg å lære små uttrykk som «skal vi ta en pause?», «hvordan gikk det i går?» og «takk for hjelpa». Jeg oppdaget at de andre ikke forventet perfekt norsk, de var bare glade for at jeg prøvde. Nå er det ofte jeg som hjelper nye ansatte med å forstå beskjedene fra sjefen. Vi ler av misforståelser sammen, og jeg kjenner at jobb ikke bare handler om lønn og oppgaver, men også om å høre til i et fellesskap på arbeidsplassen.	Då eg fekk min første jobb i Noreg, var eg mest nervøs for språket. Eg visste at eg kunne gjere sjølve arbeidet, men eg var redd for kaffipausar og småprat. På dei første vaktene sat eg ofte stille og berre lytta. Eg forsto kanskje halvparten av det kollegaene mine sa, og eg brukte lang tid på å våge å stille spørsmål. Etter kvart begynte eg å lære små uttrykk som «skal vi ta ein pause?», «korleis gjekk det i går?» og «takk for hjelpa». Eg oppdaga at dei andre ikkje venta perfekt norsk, dei var berre glade for at eg prøvde. No er det ofte eg som hjelper nye tilsette med å forstå beskjedane frå sjefen. Vi ler av misforståingar saman, og eg kjenner at jobb ikkje berre handlar om løn og oppgåver, men òg om å høyre til i eit fellesskap på arbeidsplassen.	When I got my first job in Norway, I was most nervous about the language. I knew that I could do the actual work, but I was afraid of coffee breaks and small talk. During the first shifts I often sat quietly and just listened. I understood maybe half of what my colleagues said, and it took me a long time to dare to ask questions. Gradually I started to learn small expressions like “shall we take a break?”, “how did it go yesterday?” and “thanks for the help”. I discovered that the others did not expect perfect Norwegian, they were just happy that I tried. Now it is often me who helps new employees to understand the messages from the boss. We laugh at misunderstandings together, and I feel that work is not only about salary and tasks, but also about belonging to a community at the workplace.	New colleagues and language	Nye kollegaer og språk	Nye kollegaer og språk	Новые коллеги и язык
23	Arbeidsmiljø og balanse	b2-bm-at-work	bokmaal	B2	Etter nokre år i arbeidslivet har eg forstått kor mykje arbeidsmiljøet betyr for kvardagen. Lønn og kontrakt er viktig, men det er ikkje nok dersom ein går heim med klump i magen kvar dag. På den førre arbeidsplassen min var det mykje stress og lite tid til å snakke saman. Feil blei raskt peika ut, medan god innsats nesten aldri blei nemnt. Mange var ofte sjuke eller sliten, og praten i garderoben handla mest om å telle dagar til ferie. Då eg bytte jobb, bestemte eg meg for å vere meir open om kva eg treng for å ha det bra på jobb: tydelege beskjedar, moglegheit til å stille spørsmål og ein sjef som òg tåler å høyre ordet «nei». No opplever eg at vi snakkar meir om korleis vi har det, ikkje berre om kva vi rekk. Det gjer det lettare å finne balansen mellom jobb og fritid, og å kjenne stoltheit over det vi faktisk får til saman, sjølv på travle dagar.	После нескольких лет трудовой жизни я понял, насколько важна рабочая атмосфера для обычных будней. Зарплата и контракт важны, но этого недостаточно, если каждый день уходишь домой с тяжестью в животе. На моей прошлой работе было много стресса и мало времени поговорить друг с другом. Ошибки быстро замечали и подчеркивали, а хорошее старание почти никогда не отмечали. Многие часто болели или чувствовали себя выжатыми, и разговоры в раздевалке в основном были о том, сколько дней осталось до отпуска. Когда я сменил работу, я решил быть более открытым о том, что мне нужно, чтобы чувствовать себя хорошо на работе: понятные требования, возможность задавать вопросы и начальник, который тоже способен выслушать слово «nei». Сейчас я чувствую, что мы больше говорим о том, как мы себя чувствуем, а не только о том, сколько успеваем сделать. Это помогает легче находить баланс между работой и свободным временем и чувствовать гордость за то, чего мы действительно добиваемся вместе, даже в самые напряжённые дни.	["B2", "work", "environment", "balance", "wellbeing"]	t	2025-12-03 14:44:0