ous workplace there was a lot of stress and little time to talk together. Mistakes were quickly pointed out, while good effort was almost never mentioned. Many were often ill or exhausted, and the talk in the changing room was mostly about counting days until the holidays. When I changed jobs, I decided to be more open about what I need to feel well at work: clear messages, the possibility to ask questions and a manager who can also tolerate hearing the word “no”. Now I experience that we talk more about how we are doing, not only about what we manage to do. That makes it easier to find balance between work and free time and to feel pride in what we actually achieve together, even on busy days.	Working environment and balance	Arbeidsmiljø og balanse	Arbeidsmiljø og balanse	Рабочая атмосфера и баланс
24	Mekaniker på fabrikken	a1-bm-industrial-mechanic	bokmaal	A1	Jeg heter Ivan, og jeg jobber som mekaniker på en fabrikk. Vi lager metall­deler til maskiner. Hver morgen tar jeg på meg arbeidsklær, vernesko, hjelm og hørselvern før jeg går inn i hallen. Det er mange store maskiner som lager høy lyd. Først går jeg en runde og ser om alt ser normalt ut. Jeg lytter etter rare lyder og kjenner om en motor er for varm. Hvis en bolt er løs, finner jeg en nøkkel og skrur den fast. Noen ganger må jeg bytte et lite hjul eller et belte. Da stopper vi maskinen, låser strømmen og jobber rolig og sikkert. Jeg liker å se at maskinen starter igjen, og at produksjonen går som den skal. Da vet jeg at jeg har gjort en viktig jobb.	Меня зовут Иван, и я работаю механиком на заводе. Мы делаем металлические детали для разных машин. Каждое утро я надеваю рабочую одежду, защитную обувь, каску и наушники, защищающие слух, прежде чем зайти в цех. Там много больших станков, которые сильно шумят. Сначала я обхожу линию и смотрю, всё ли выглядит нормально. Я прислушиваюсь к странным звукам и проверяю, не слишком ли горячий мотор. Если какой‑то болт ослаб, я беру ключ и затягиваю его. Иногда нужно поменять маленькое колесо или ремень. Тогда мы останавливаем станок, отключаем и блокируем питание и работаем спокойно и безопасно. Мне нравится видеть, как машина снова запускается и производство идёт как надо. Тогда я знаю, что сделал важную работу.	["A1", "work", "mechanic", "factory", "maintenance"]	t	2025-12-04 08:16:36.821199+00	2025-12-04 08:16:36.821214+00	Jeg heter Ivan, og jeg jobber som mekaniker på en fabrikk. Vi lager metall­deler til maskiner. Hver morgen tar jeg på meg arbeidsklær, vernesko, hjelm og hørselvern før jeg går inn i hallen. Det er mange store maskiner som lager høy lyd. Først går jeg en runde og ser om alt ser normalt ut. Jeg lytter etter rare lyder og kjenner om en motor er for varm. Hvis en bolt er løs, finner jeg en nøkkel og skrur den fast. Noen ganger må jeg bytte et lite hjul eller et belte. Da stopper vi maskinen, låser strømmen og jobber rolig og sikkert. Jeg liker å se at maskinen starter igjen, og at produksjonen går som den skal. Da vet jeg at jeg har gjort en viktig jobb.	Eg heiter Ivan, og eg jobbar som mekanikar på ein fabrikk. Vi lagar metalldelar til maskiner. Kvar morgon tek eg på meg arbeidsklede, vernesko, hjelm og øyra­vern før eg går inn i hallen. Det er mange store maskiner som lagar høg lyd. Først går eg ein runde og ser om alt ser normalt ut. Eg lyttar etter rare lydar og kjenner om ein motor er for varm. Dersom ein bolt er laus, finn eg ein nøkkel og skrur han fast. Nokre gonger må eg bytte eit lite hjul eller eit belte. Då stoppar vi maskina, låser straumen og jobbar roleg og trygt. Eg liker å sjå at maskina startar igjen, og at produksjonen går som han skal. Då veit eg at eg har gjort ein viktig jobb.	My name is Ivan, and I work as a mechanic in a factory. We make metal parts for machines. Every morning I put on work clothes, safety shoes, a helmet and hearing protection before I go into the hall. There are many big machines that make a lot of noise. First I walk around and see if everything looks normal. I listen for strange sounds and feel if a motor is too hot. If a bolt is loose, I find a spanner and tighten it. Sometimes I have to change a small wheel or a belt. Then we stop the machine, lock the power and work calmly and safely. I like to see the machine start again and the production run as it should. Then I know that I have done an important job.	Mechanic at the factory	Mekaniker på fabrikken	Mekanikar på fabrikken	Механик на заводе
25	Feilsøking på produksjonslinja	a2-bm-industrial-mechanic	bokmaal	A2	Jeg jobber som mekaniker med vedlikehold og feilsøking på produksjonsutstyret. Når jeg kommer på jobb, leser jeg først rapporten fra kveldsskiftet. Der står det om noen maskiner har stoppet, og om operatørene har hørt rare lyder eller sett lekkasje. I dag har en av pakkemaskinene stoppet flere ganger. Jeg går bort til linja og snakker med operatøren. Han forklarer at maskinen bråker når den starter, og at båndet plutselig stopper. Først sjekker jeg om alle sensorer er rene, og om det ligger noe fast mellom hjulene. Etterpå åpner jeg dekselet og ser at et lite tannhjul er slitt. Jeg bestiller en ny del i dataprogrammet vårt, men midlertidig kan jeg stramme kjedet slik at maskinen kan gå sakte videre. Vi skriver en beskjed til neste skift, så alle vet hva som er gjort, og hva vi skal gjøre når den nye delen kommer.	Я работаю механиком по обслуживанию и поиску неисправностей на производственном оборудовании. Когда я прихожу на работу, я сначала читаю отчёт от вечерней смены. Там написано, какие машины останавливались и слышали ли операторы странные звуки или видели утечку. Сегодня одна из упаковочных машин несколько раз останавливалаcь. Я подхожу к линии и разговариваю с оператором. Он объясняет, что машина шумит при запуске и что лента внезапно останавливается. Сначала я проверяю, чистые ли все датчики и не застряло ли что‑то между колёсами. Потом открываю кожух и вижу, что маленькая шестерёнка изношена. Я заказываю новую деталь в нашей компьютерной системе, но временно могу подтянуть цепь, чтобы машина могла медленно продолжать работу. Мы пишем сообщение для следующей смены, чтобы все знали, что сделано и что мы будем делать, когда придёт новая деталь.	["A2", "work", "mechanic", "factory", "troubleshooting"]	t	2025-12-04 08:16:36.826374+00	2025-12-04 08:16:36.826386+00	Jeg jobber som mekaniker med vedlikehold og feilsøking på produksjonsutstyret. Når jeg kommer på jobb, leser jeg først rapporten fra kveldsskiftet. Der står det om noen maskiner har stoppet, og om operatørene har hørt rare lyder eller sett lekkasje. I dag har en av pakkemaskinene stoppet flere ganger. Jeg går bort til linja og snakker med operatøren. Han forklarer at maskinen bråker når den starter, og at båndet plutselig stopper. Først sjekker jeg om alle sensorer er rene, og om det ligger noe fast mellom hjulene. Etterpå åpner jeg dekselet og ser at et lite tannhjul er slitt. Jeg bestiller en ny del i dataprogrammet vårt, men midlertidig kan jeg stramme kjedet slik at maskinen kan gå sakte videre. Vi skriver en beskjed til neste skift, så alle vet hva som er gjort, og hva vi skal gjøre når den nye delen kommer.	Eg jobbar som mekanikar med vedlikehald og feil­søking på produksjonsutstyret. Når eg kjem på jobb, les eg først rapporten frå kveldsskiftet. Der står det om nokre maskiner har stoppa, og om operatørane har høyrt rare lydar eller sett lekkasje. I dag har ei av pakkemaskinene stoppa fleire gonger. Eg går bort til lina og snakkar med operatøren. Han forklarer at maskina bråkar når ho startar, og at bandet plutseleg stoppar. Først sjekkar eg om alle sensorar er reine, og om det ligg noko fast mellom hjula. Etterpå opnar eg dekslet og ser at eit lite tannhjul er slite. Eg bestiller ein ny del i dataprogrammet vårt, men midlertidig kan eg stramme kjedet slik at maskina kan gå sakte vidare. Vi skriv ei melding til neste skift, slik at alle veit kva som er gjort, og kva vi skal gjere når den nye delen kjem.	I work as a mechanic with maintenance and troubleshooting on the production equipment. When I arrive at work, I first read the report from the evening shift. There it says if any machines have stopped, and if the operators have heard strange sounds or seen leakage. Today one of the packing machines has stopped several times. I go to the line and talk to the operator. He explains that the machine makes noise when it starts and that the belt suddenly stops. First I check if all the sensors are clean and if something is stuck between the wheels. Afterwards I open the cover and see that a small gear wheel is worn. I order a new part in our computer system, but for now I can tighten the chain so that the machine can continue slowly. We write a message to the next shift so everyone knows what has been done and what we will do when the new part arrives.	Troubleshooting on the production line	Feilsøking på produksjonslinja	Feilsøking på produksjonslina	Поиск неисправностей на линии
26	Mitt første store stopp	b1-bm-industrial-mechanic	bokmaal	B1	Den første gangen jeg hadde ansvar for et stort maskinstopp alene, glemmer jeg aldri. Det var midt på dagvakta, og produksjonslinja gikk for fullt. Plutselig kom det alarm på skjermen, og hele linja stoppet. Operatøren ringte meg med en gang, og jeg kjente at hjertet slo litt fortere. Jeg visste at hvert minutt uten produksjon kostet mye penger. Samtidig måtte jeg holde hodet kaldt. Først leste jeg feilkoden på skjermen og skrev den ned. Så brukte jeg det jeg hadde lært på kurs: sjekke strømtilførsel, sensorer og mekaniske deler i riktig rekkefølge. Etter noen minutter fant jeg årsaken: en liten sensor som «ser» produktene på båndet, hadde sklidd litt ut av posisjon. Jeg justerte den forsiktig og testet maskinen steg for steg. Da linja startet igjen, klappet operatøren meg på skulderen og sa at det var bra jobbet. Jeg gikk tilbake til verkstedet med en ny erfaring: som mekaniker handler jobben ikke bare om verktøy, men også om å holde roen når mange venter på at du skal løse problemet.	Я никогда не забуду первый раз, когда за большой останов производственной линии отвечал только я один. Это было посреди дневной смены, линия шла на полной скорости. Вдруг на экране появилась аварийная сигнализация, и вся линия остановилась. Оператор сразу позвонил мне, и я почувствовал, как сердце забилось быстрее. Я знал, что каждая минута без производства стоит больших денег. В то же время нужно было сохранить холодную голову. Сначала я прочитал код ошибки на экране и записал его. Потом сделал то, чему нас учили на курсах: проверить питание, датчики и механические части в правильном порядке. Через несколько минут я нашёл причину: маленький датчик, который «видит» продукт на ленте, немного сместился. Я аккуратно отрегулировал его и протестировал машину шаг за шагом. Когда линия снова запустилась, оператор похлопал меня по плечу и сказал, что я хорошо справился. Я вернулся в мастерскую с новым опытом: работа механика — это не только инструмент, но и умение сохранять спокойствие, когда многие ждут, что именно ты решишь проблему.	["B1", "work", "mechanic", "factory", "experience"]	t	2025-12-04 08:16:36.830564+00	2025-12-04 08:16:36.830579+00	Den første gangen jeg hadde ansvar for et stort maskinstopp alene, glemmer jeg aldri. Det var midt på dagvakta, og produksjonslinja gikk for fullt. Plutselig kom det alarm på skjermen, og hele linja stoppet. Operatøren ringte meg med en gang, og jeg kjente at hjertet slo litt fortere. Jeg visste at hvert minutt uten produksjon kostet mye penger. Samtidig måtte jeg holde hodet kaldt. Først leste jeg feilkoden på skjermen og skrev den ned. Så brukte jeg det jeg hadde lært på kurs: sjekke strømtilførsel, sensorer og mekaniske deler i riktig rekkefølge. Etter noen minutter fant jeg årsaken: en liten sensor som «ser» produktene på båndet, hadde sklidd litt ut av posisjon. Jeg justerte den forsiktig og testet maskinen steg for steg. Da linja startet igjen, klappet operatøren meg på skulderen og sa at det var bra jobbet. Jeg gikk tilbake til verkstedet med en ny erfaring: som mekaniker handler jobben ikke bare om verktøy, men også om å holde roen når mange venter på at du skal løse problemet.	Den første gongen eg hadde ansvar for eit stort maskinstopp åleine, gløymer eg aldri. Det var midt på dagvakta, og produksjonslina gjekk for fullt. Plutseleg kom det alarm på skjermen, og heile lina stoppa. Operatøren ringde meg med ein gong, og eg kjende at hjartet slo litt fortare. Eg visste at hvert minutt utan produksjon kosta mykje pengar. Samstundes måtte eg halde hovudet kaldt. Først las eg feilkoden på skjermen og skreiv han ned. Så brukte eg det eg hadde lært på kurs: sjekke straumtilførsel, sensorar og mekaniske delar i riktig rekkjefølgje. Etter nokre minutt fann eg årsaka: ein liten sensor som «ser» produkta på bandet, hadde gli litt ut av posisjon. Eg justerte han forsiktig og testa maskina steg for steg. Då lina starta igjen, klappa operatøren meg på skuldra og sa at det var bra jobba. Eg gjekk tilbake til verkstaden med ei ny erfaring: som mekanikar handlar jobben ikkje berre om verktøy, men òg om å halde roen når mange ventar på at du skal løyse problemet.	I will never forget the first time I was responsible for a big machine stop on my own. It was in the middle of the day shift, and the production line was running at full speed. Suddenly an alarm appeared on the screen, and the whole line stopped. The operator called me at once, and I felt my heart beating faster. I knew that every minute without production cost a lot of money. At the same time I had to keep a cool head. First I read the error code on the screen and wrote it down. Then I used what I had learnt on courses: check the power supply, sensors and mechanical parts in the right order. After a few minutes I found the cause: a small sensor that “sees” the products on the belt had moved slightly out of position. I adjusted it carefully and tested the machine step by step. When the line started again, the operator patted me on the shoulder and said I had done a good job. I went back to the workshop with a new experience: as a mechanic the job is not only about tools, but also about keeping calm when many people are waiting for you to solve the problem.	My first big stop	Mitt første store stopp	Mitt første store stopp	Моя первая большая остановка
27	Mekanikeren i produksjonen	b2-bm-industrial-mechanic	bokmaal	B2	Jo lengre eg jobbar som mekaniker på fabrikk, desto meir ser eg kor viktig godt vedlikehald er for heile produksjonen. Når alt går som det skal, er det nesten ingen som tenker på oss i verkstaden. Men kvar gong ei linje stoppar, blir det tydeleg kor sårbart systemet er. For meg handlar jobben etter kvart like mykje om å førebygge stopp som å reparere når noko allereie har gått gale. Vi lagar vedlikeholdsplanar, set opp faste kontrollpunkt og prøver å få operatørane til å seie frå tidleg når dei høyrer nye lydar eller kjenner vibrasjonar. Samtidig må vi forklare for leiinga kvifor det lønner seg å stoppe ei maskin ein time for service i dag, i staden for å miste ein heil dag med produksjon neste veke. Som mekaniker står eg midt mellom teknikken og menneska: mellom teikningar, reservedelar og feilkodar på den eine sida, og stressa operatørar og produksjonskrav på den andre. Når vi lukkast, merkar kanskje ingen det der og då – men dei ser det på færre stopp, tryggare arbeidsplass og leveransar som kjem fram i tide.	Чем дольше я работаю механиком на заводе, тем больше вижу, насколько важное значение имеет хорошее обслуживание для всего производства. Когда всё работает как надо, почти никто не думает о нас, кто сидит в мастерской. Но каждый раз, когда линия останавливается, становится ясно, насколько система уязвима. Для меня работа всё больше связана не только с ремонтом поломок, но и с профилактикой остановов. Мы составляем планы обслуживания, делаем регулярные контрольные точки и стараемся, чтобы операторы заранее сообщали, если слышат новые звуки или чувствуют вибрации. Одновременно мы должны объяснять руководству, почему выгоднее остановить машину на час обслуживания сегодня, чем потерять целый день производства на следующей неделе. Механик стоит посередине между техникой и людьми: между чертежами, запчастями и кодами ошибок — с одной стороны, и уставшими операторами и планами производства — с другой. Когда у нас всё получается, этого, может быть, никто не замечает сразу, но это видно по меньшему количеству остановок, более безопасному рабочему месту и поставкам, которые приходят вовремя.	["B2", "work", "mechanic", "factory", "maintenance", "system"]	t	2025-12-04 08:16:36.840982+00	2025-12-04 08:16:36.840998+00	Jo lengre eg jobbar som mekaniker på fabrikk, desto meir ser eg kor viktig godt vedlikehald er for heile produksjonen. Når alt går som det skal, er det nesten ingen som tenker på oss i verkstaden. Men kvar gong ei linje stoppar, blir det tydeleg kor sårbart systemet er. For meg handlar jobben etter kvart like mykje om å førebygge stopp som å reparere når noko allereie har gått gale. Vi lagar vedlikeholdsplanar, set opp faste kontrollpunkt og prøver å få operatørane til å seie frå tidleg når dei høyrer nye lydar eller kjenner vibrasjonar. Samtidig må vi forklare for leiinga kvifor det lønner seg å stoppe ei maskin ein time for service i dag, i staden for å miste ein heil dag med produksjon neste veke. Som mekaniker står eg midt mellom teknikken og menneska: mellom teikningar, reservedelar og feilkodar på den eine sida, og stressa operatørar og produksjonskrav på den andre. Når vi lukkast, merkar kanskje ingen det der og då – men dei ser det på færre stopp, tryggare arbeidsplass og leveransar som kjem fram i tide.	Jo lengre eg jobbar som mekanikar på fabrikk, desto meir ser eg kor viktig godt vedlikehald er for heile produksjonen. Når alt går som det skal, er det nesten ingen som tenkjer på oss i verkstaden. Men kvar gong ei line stoppar, blir det tydeleg kor sårbart systemet er. For meg handlar jobben etter kvart like mykje om å førebyggje stopp som å reparere når noko allereie har gått gale. Vi lagar vedlikehaldsplanar, set opp faste kontrollpunkt og prøver å få operatørane til å seie frå tidleg når dei høyrer nye lydar eller kjenner vibrasjonar. Samstundes må vi forklare for leiinga kvifor det lønner seg å stoppe ei maskin ein time for service i dag, i staden for å miste ein heil dag med produksjon neste veke. Som mekanikar står eg midt mellom teknikken og menneska: mellom teikningar, reservedelar og feilkodar på den eine sida, og stressa operatørar og produksjonskrav på den andre. Når vi lukkast, merkar kanskje ingen det der og då – men dei ser det på færre stopp, tryggare arbeidsplass og leveransar som kjem fram i tide.	The longer I work as a mechanic in a factory, the more I see how important good maintenance is for the whole production. When everything runs as it should, almost nobody thinks about us in the workshop. But every time a line stops, it becomes clear how vulnerable the system is. For me the job is now just as much about preventing stops as about repairing when something has already gone wrong. We make maintenance plans, set up fixed checkpoints and try to get the operators to report early when they hear new sounds or feel vibrations. At the same time we have to explain to the management why it pays to stop a machine for an hour of service today instead of losing a whole day of production next week. As a mechanic I stand in the middle between technology and people: between drawings, spare parts and error codes on one side, and stressed operators and production demands on the other. When we succeed, maybe nobody notices it right then – but they see it in fewer stops, a safer workplace and deliveries that arrive on time.	The mechanic in the production	Mekanikeren i produksjonen	Mekanikaren i produksjonen	Роль механика в производстве
28	Liten reparasjon på transportbåndet	a1-bm-equipment-repair	bokmaal	A1	Jeg heter Amir, og jeg jobber som mekaniker på en produksjonslinje. I dag skal jeg reparere en liten del på et transportbånd. Ett av hjulene som bærer båndet, går tungt og lager en rar lyd. Før jeg begynner, stopper vi linja og slår av strømmen. Jeg låser bryteren og henger på en rød lapp der det står «IKKE START». Så finner jeg frem verktøy: fastnøkler, skrutrekker og en liten hammer. Jeg skrur av dekselet, tar av det gamle hjulet og tørker bort fett og skitt med en klut. Det nye hjulet legger jeg på samme plass og skrur mutteren godt fast. Til slutt snur jeg hjulet med hånda for å sjekke at det går lett. Når vi starter linja igjen, går båndet stille og fint. Da smiler operatøren og sier takk for hjelpen.	Меня зовут Амир, и я работаю механиком на производственной линии. Сегодня я буду ремонтировать небольшой узел на конвейере. Одно из роликовых колёс, которые держат ленту, тяжело крутится и издаёт странный звук. Прежде чем начать, мы останавливаем линию и выключаем питание. Я блокирую выключатель и вешаю красную бирку с надписью «IKKE START» («НЕ ЗАПУСКАТЬ»). Потом беру инструмент: гаечные ключи, отвёртку и маленький молоток. Я снимаю кожух, снимаю старый ролик и вытираю тряпкой грязь и смазку. Новый ролик ставлю на то же место и хорошо затягиваю гайку. В конце проворачиваю ролик рукой, чтобы проверить, легко ли он крутится. Когда мы снова запускаем линию, лента идёт тихо и ровно. Тогда оператор улыбается и говорит спасибо за помощь.	["A1", "work", "mechanic", "repair", "tools", "conveyor"]	t	2025-12-04 08:40:31.42234+00	2025-12-04 08:40:31.422353+00	Jeg heter Amir, og jeg jobber som mekaniker på en produksjonslinje. I dag skal jeg reparere en liten del på et transportbånd. Ett av hjulene som bærer båndet, går tungt og lager en rar lyd. Før jeg begynner, stopper vi linja og slår av strømmen. Jeg låser bryteren og henger på en rød lapp der det står «IKKE START». Så finner jeg frem verktøy: fastnøkler, skrutrekker og en liten hammer. Jeg skrur av dekselet, tar av det gamle hjulet og tørker bort fett og skitt med en klut. Det nye hjulet legger jeg på samme plass og skrur mutteren godt fast. Til slutt snur jeg hjulet med hånda for å sjekke at det går lett. Når vi starter linja igjen, går båndet stille og fint. Da smiler operatøren og sier takk for hjelpen.	Eg heiter Amir, og eg jobbar som mekanikar på ei produksjonsline. I dag skal eg reparere ein liten del på eit transportband. Eitt av hjula som ber bandet, går tungt og lagar ein rar lyd. Før eg begynner, stoppar vi lina og slår av straumen. Eg låser brytaren og heng på ein raud lapp der det står «IKKJE START». Så finn eg fram verktøy: fastnøklar, skrutrekker og ein liten hammer. Eg skrur av dekslet, tek av det gamle hjulet og tørkar bort feitt og skit med ein klut. Det nye hjulet legg eg på same plass og skrur mutteren godt fast. Til slutt snur eg hjulet med handa for å sjekke at det går lett. Når vi startar lina igjen, går bandet stille og fint. Då smiler operatøren og seier takk for hjelpa.	My name is Amir, and I work as a mechanic on a production line. Today I am going to repair a small part on a conveyor belt. One of the rollers that carries the belt is heavy to turn and makes a strange sound. Before I start, we stop the line and turn off the power. I lock the switch and hang a red tag that says “DO NOT START”. Then I find my tools: spanners, a screwdriver and a small hammer. I unscrew the cover, take off the old roller and wipe away grease and dirt with a cloth. I put the new roller in the same place and tighten the nut well. Finally I turn the roller by hand to check that it moves easily. When we start the line again, the belt runs quietly and nicely. Then the operator smiles and says thank you for the help.	Small repair on the conveyor belt	Liten reparasjon på transportbåndet	Lita reparasjon på transportbandet	Небольшой ремонт на конвейере
29	Bytte lager på motoren	a2-bm-equipment-repair	bokmaal	A2	På fabrikken der jeg jobber, har vi en planlagt stopp på produksjonslinja for å reparere en lagerblokk på en motor. Motoren driver et langt transportbånd, og i det siste har den blitt varm og laget vibrasjon. Før vi begynner, går jeg og kollegaen min gjennom jobben trinn for trinn. Vi skriver på tavla hva vi skal gjøre, og hvilket verktøy og hvilke deler vi trenger: momentnøkkel, avtrekker, nye lager og frisk fett. Når linja er stoppet og strømmen er låst, løsner vi dekslene rundt motoren. Jeg merker av posisjonen på koblingen med tusj, så vi kan montere alt på samme måte etterpå. Deretter skrur vi av lagerhuset og bruker avtrekkeren til å ta ut det gamle lageret. Vi rengjør akselen nøye før vi presser inn det nye lageret. Til slutt smører vi med nytt fett, monterer alt tilbake og tester motoren på lav hastighet. Når den går rolig uten vibrasjon, skriver vi ferdig rapporten i systemet og åpner linja for produksjon igjen.	На заводе, где я работаю, у нас запланирован останов производственной линии, чтобы отремонтировать корпус подшипника на электродвигателе. Двигатель приводит в движение длинный транспортер, и в последнее время он стал сильно нагреваться и вызывать вибрацию. Перед началом мы с напарником проходим всю работу шаг за шагом. Пишем на доске, что будем делать и какие инструменты и детали нужны: динамометрический ключ, съёмник, новые подшипники и свежая смазка. Когда линия остановлена и питание заблокировано, мы снимаем кожухи вокруг двигателя. Я помечаю маркером положение муфты, чтобы потом собрать всё в том же положении. Потом откручиваем корпус подшипника и с помощью съёмника вынимаем старый подшипник. Тщательно очищаем вал, прежде чем запрессовать новый подшипник. В конце закладываем свежую смазку, собираем всё обратно и тестируем двигатель на малой скорости. Когда он работает ровно, без вибрации, мы заполняем отчёт в системе и снова открываем линию для производства.	["A2", "work", "mechanic", "repair", "bearing", "motor"]	t	2025-12-04 08:40:31.427779+00	2025-12-04 08:40:31.427801+00	På fabrikken der jeg jobber, har vi en planlagt stopp på produksjonslinja for å reparere en lagerblokk på en motor. Motoren driver et langt transportbånd, og i det siste har den blitt varm og laget vibrasjon. Før vi begynner, går jeg og kollegaen min gjennom jobben trinn for trinn. Vi skriver på tavla hva vi skal gjøre, og hvilket verktøy og hvilke deler vi trenger: momentnøkkel, avtrekker, nye lager og frisk fett. Når linja er stoppet og strømmen er låst, løsner vi dekslene rundt motoren. Jeg merker av posisjonen på koblingen med tusj, så vi kan montere alt på samme måte etterpå. Deretter skrur vi av lagerhuset og bruker avtrekkeren til å ta ut det gamle lageret. Vi rengjør akselen nøye før vi presser inn det nye lageret. Til slutt smører vi med nytt fett, monterer alt tilbake og tester motoren på lav hastighet. Når den går rolig uten vibrasjon, skriver vi ferdig rapporten i systemet og åpner linja for produksjon igjen.	På fabrikken der eg jobbar, har vi ein planlagd stopp på produksjonslina for å reparere ein lagerblokk på ein motor. Motoren driv eit langt transportband, og i det siste har han blitt varm og laga vibrasjon. Før vi begynner, går eg og kollegaen min gjennom jobben trinn for trinn. Vi skriv på tavla kva vi skal gjere, og kva verktøy og delar vi treng: momentnøkkel, avtrekkar, nye lager og frisk feitt. Når lina er stoppa og straumen er låst, løyser vi dekselet rundt motoren. Eg merker av posisjonen på koplinga med tusj, slik at vi kan montere alt på same måte etterpå. Deretter skrur vi av lagerhuset og brukar avtrekkaren til å ta ut det gamle lageret. Vi reingjer akselen nøye før vi pressar inn det nye lageret. Til slutt smører vi med nytt feitt, monterer alt tilbake og testar motoren på låg hastigheit. Når han går roleg utan vibrasjon, skriv vi ferdig rapporten i systemet og opnar lina for produksjon igjen.	At the factory where I work, we have a planned stop on the production line to repair a bearing block on a motor. The motor drives a long conveyor, and lately it has become hot and created vibration. Before we start, my colleague and I go through the job step by step. We write on the board what we are going to do and which tools and parts we need: torque wrench, puller, new bearings and fresh grease. When the line is stopped and the power is locked, we loosen the covers around the motor. I mark the position of the coupling with a marker so that we can mount everything in the same way afterwards. Then we unscrew the bearing housing and use the puller to remove the old bearing. We clean the shaft carefully before we press in the new bearing. Finally we grease with new grease, mount everything back and test the motor at low speed. When it runs smoothly without vibration, we complete the report in the system and open the line for production again.	Changing the bearing on the motor	Bytte lager på motoren	Byte lager på motoren	Замена подшипника на двигателе
30	Demontering av ei gammal girkasse	b1-bm-equipment-repair	bokmaal	B1	Forrige uke hadde vi en krevende reparasjon på en av de eldste linjene våre. En girkasse som driver kjeden på pakkebordet, begynte å lekke olje, og operatørene hørte kneppelyder hver gang linja startet. Vi bestemte oss for å demontere hele girkassa i stedet for å bare fylle på mer olje. Etter at vi hadde låst strømmen og merket av alle brytere, tok vi av kjededekselet og løsnet boltene som holdt girkassa på plass. Den var tyngre enn vi trodde, så vi hentet en liten traverskran for å løfte den forsiktig ned på et rent arbeidsbord. Inne i girkassa fant vi både slitte tannhjul og en gammel pakning som nesten var borte. Vi la delene i rekkefølge på bordet, tok bilder med mobilen og sammenlignet med tegningen i manualen. Det tok tid å rense alt for gammel olje og metallstøv, men til slutt kunne vi montere inn nye tannhjul og pakninger. Da vi satte girkassa tilbake og testet linja med lav hastighet, var lyden borte, og operatørene slapp å stå og lure på når neste stopp skulle komme.	На прошлой неделе у нас был сложный ремонт на одной из самых старых линий. Редуктор, который приводит в движение цепь на упаковочном столе, начал течь маслом, а операторы слышали щёлкающие звуки каждый раз при пуске линии. Мы решили полностью разобрать редуктор, а не просто доливать масло. После того как мы заблокировали питание и пометили все выключатели, сняли кожух цепи и открутили болты, которые держали редуктор. Он оказался тяжелее, чем мы думали, поэтому мы взяли небольшой кран-балку и аккуратно опустили его на чистый верстак. Внутри редуктора мы нашли и изношенные шестерни, и старую прокладку, которой почти не осталось. Мы разложили детали по порядку на столе, сделали фото на телефон и сверились с чертежом в инструкции. На уборку старого масла и металлической стружки ушло немало времени, но в конце мы смогли установить новые шестерни и прокладки. Когда мы поставили редуктор обратно и протестировали линию на малой скорости, посторонний звук исчез, и операторам больше не пришлось гадать, когда случится следующая остановка.	["B1", "work", "mechanic", "repair", "gearbox", "experience"]	t	2025-12-04 08:40:31.43295+00	2025-12-04 08:40:31.432965+00	Forrige uke hadde vi en krevende reparasjon på en av de eldste linjene våre. En girkasse som driver kjeden på pakkebordet, begynte å lekke olje, og operatørene hørte kneppelyder hver gang linja startet. Vi bestemte oss for å demontere hele girkassa i stedet for å bare fylle på mer olje. Etter at vi hadde låst strømmen og merket av alle brytere, tok vi av kjededekselet og løsnet boltene som holdt girkassa på plass. Den var tyngre enn vi trodde, så vi hentet en liten traverskran for å løfte den forsiktig ned på et rent arbeidsbord. Inne i girkassa fant vi både slitte tannhjul og en gammel pakning som nesten var borte. Vi la delene i rekkefølge på bordet, tok bilder med mobilen og sammenlignet med tegningen i manualen. Det tok tid å rense alt for gammel olje og metallstøv, men til slutt kunne vi montere inn nye tannhjul og pakninger. Da vi satte girkassa tilbake og testet linja med lav hastighet, var lyden borte, og operatørene slapp å stå og lure på når neste stopp skulle komme.	Førre veke hadde vi ein krevjande reparasjon på ei av dei eldste linene våre. Ei girkasse som driv kjeda på pakkebordet, hadde begynt å lekke olje, og operatørane høyrde kneppelydar kvar gong lina starta. Vi bestemte oss for å demontere heile girkassa i staden for berre å fylle på meir olje. Etter at vi hadde låst straumen og merka av alle brytarar, tok vi av kjededekselet og løyse boltene som heldt girkassa på plass. Ho var tyngre enn vi trudde, så vi henta ein liten traverskran for å løfte henne forsiktig ned på ein rein arbeidsbenk. Inne i girkassa fann vi både slitte tannhjul og ein gammal pakning som nesten var borte. Vi la delane i rekkjefølgje på bordet, tok bilete med mobilen og samanlikna med teikninga i manualen. Det tok tid å rense alt for gammal olje og metallstøv, men til slutt kunne vi montere inn nye tannhjul og pakningar. Då vi sette girkassa tilbake og testa lina med låg hastigheit, var lyden borte, og operatørane slapp å stå og lure på når neste stopp kom til å kome.	Last week we had a demanding repair on one of our oldest lines. A gearbox that drives the chain on the packing table had started to leak oil, and the operators heard clicking noises every time the line started. We decided to dismantle the whole gearbox instead of just filling up more oil. After we had locked the power and marked all switches, we removed the chain cover and loosened the bolts that held the gearbox in place. It was heavier than we thought, so we fetched a small overhead crane to lift it carefully down onto a clean workbench. Inside the gearbox we found both worn gears and an old gasket that was almost gone. We put the parts in order on the table, took photos with the phone and compared them with the drawing in the manual. It took time to clean everything from old oil and metal dust, but in the end we could mount new gears and gaskets. When we put the gearbox back and tested the line at low speed, the noise was gone, and the operators no longer had to stand and wonder when the next stop would come.	Dismantling an old gearbox	Demontering av en gammel girkasse	Demontering av ei gammal girkasse	Разборка старого редуктора
31	Frå reparasjon til læring	b2-bm-equipment-repair	bokmaal	B2	Ein konkret reparasjonsjobb kan også bli ein viktig læringssituasjon for heile fabrikken. Nyleg hadde vi ein havari på ein drivstasjon der eit lager hadde gått heilt i stykker og øydelagt både aksel og tetningar. I staden for berre å bestille nye delar og «få det i gang igjen», bestemte vi oss for å bruke litt ekstra tid. Vi demonterte heile eininga på verkstaden, målte slitasje på akselen, såg på kor smørja hadde lagt seg, og samanlikna med intervalla i vedlikehaldsplanen. Samtidig snakka vi med operatørane om når dei først hadde høyrt unormal lyd, og kvifor det tok ei stund før dei sa ifrå. Etter at vi hadde bytt aksel, lager og tetningar, skreiv vi ikkje berre ein vanleg jobb­rapport, men også eit kort avvik der vi foreslo endra intervall for kontroll og betre merking av lydnivå ved maskina. Slik blei ein konkret reparasjon med skrutrekkar og momentnøkkel òg ein del av eit større arbeid med å gjere linja meir robust – både teknisk og organisatorisk.	Конкретный ремонтный случай может стать важной возможностью для обучения всей фабрики. Недавно у нас произошла серьёзная авария на приводной станции: подшипник полностью разрушился и повредил и вал, и уплотнения. Вместо того чтобы просто заказать новые детали и «как‑нибудь запустить снова», мы решили потратить немного больше времени. Мы полностью разобрали узел в мастерской, замерили износ вала, посмотрели, как распределялась смазка, и сравнили это с интервалами обслуживания в плане ТО. Параллельно мы поговорили с операторами о том, когда они впервые услышали необычный звук и почему прошло время, прежде чем они сообщили об этом. После замены вала, подшипников и уплотнений мы написали не только обычный отчёт о выполненной работе, но и короткое «avvik» — сообщение об отклонении, где предложили изменить интервалы контроля и сделать лучшее обозначение допустимого уровня шума у машины. Так один конкретный ремонт со отвёрткой и динамометрическим ключом стал частью более большой работы по тому, чтобы сделать линию более устойчивой — и технически, и организационно.	["B2", "work", "mechanic", "repair", "maintenance", "learning", "system"]	t	2025-12-04 08:40:31.438691+00	2025-12-04 08:40:31.438703+00	Ein konkret reparasjonsjobb kan også bli ein viktig læringssituasjon for heile fabrikken. Nyleg hadde vi ein havari på ein drivstasjon der eit lager hadde gått heilt i stykker og øydelagt både aksel og tetningar. I staden for berre å bestille nye delar og «få det i gang igjen», bestemte vi oss for å bruke litt ekstra tid. Vi demonterte heile eininga på verkstaden, målte slitasje på akselen, såg på kor smørja hadde lagt seg, og samanlikna med intervalla i vedlikehaldsplanen. Samtidig snakka vi med operatørane om når dei først hadde høyrt unormal lyd, og kvifor det tok ei stund før dei sa ifrå. Etter at vi hadde bytt aksel, lager og tetningar, skreiv vi ikkje berre ein vanleg jobb­rapport, men også eit kort avvik der vi foreslo endra intervall for kontroll og betre merking av lydnivå ved maskina. Slik blei ein konkret reparasjon med skrutrekkar og momentnøkkel òg ein del av eit større arbeid med å gjere linja meir robust – både teknisk og organisatorisk.	Ein konkret reparasjonsjobb kan òg bli ein viktig læringssituasjon for heile fabrikken. Nyleg hadde vi eit havari på ein drivstasjon der eit lager hadde gått heilt i stykker og øydelagt både aksling og tetningar. I staden for berre å bestille nye delar og «få det i gang igjen», bestemte vi oss for å bruke litt ekstra tid. Vi demonterte heile eininga på verkstaden, målte slitasje på akslinga, såg på kor smørja hadde lagt seg, og samanlikna med intervalla i vedlikehaldsplanen. Samstundes snakka vi med operatørane om når dei først hadde høyrt unormal lyd, og kvifor det tok ei stund før dei sa ifrå. Etter at vi hadde bytt aksling, lager og tetningar, skreiv vi ikkje berre ein vanleg jobbrapport, men òg eit kort avvik der vi foreslo endra intervall for kontroll og betre merking av lydnivå ved maskina. Slik blei ein konkret reparasjon med skrutrekker og momentnøkkel òg ein del av eit større arbeid med å gjere lina meir robust – både teknisk og organisatorisk.	A concrete repair job can also become an important learning situation for the whole factory. Recently we had a breakdown on a drive station where a bearing had completely failed and damaged both the shaft and the seals. Instead of just ordering new parts and “getting it running again”, we decided to spend a little extra time. We dismantled the whole unit in the workshop, measured wear on the shaft, looked at how the grease had settled, and compared it with the intervals in the maintenance plan. At the same time we talked with the operators about when they first heard abnormal noise, and why it took some time before they reported it. After we had replaced the shaft, bearings and seals, we did not only write an ordinary job report, but also a short deviation report where we suggested changed intervals for inspection and better marking of sound levels by the machine. In this way a concrete repair with screwdriver and torque wrench also became part of a larger effort to make the line more robust – both technically and organisationally.	From repair to learning	Fra reparasjon til læring	Frå reparasjon til læring	От ремонта к обучению
32	Jeg lærer norsk	a1-bm-learning-norwegian	bokmaal	A1	Jeg heter Nadia, og jeg lærer norsk. Jeg går på norskkurs to kvelder i uka. Læreren vår er snill og snakker sakte. Først leser vi en liten tekst sammen, og etterpå snakker vi to og to. Noen ganger er jeg redd for å si feil, men læreren sier at det er lov å gjøre feil når man lærer. Hjemme prøver jeg å bruke litt norsk hver dag. Jeg skriver handleliste på norsk, og jeg sier «takk», «unnskyld» og «ha det» til folk i butikken. Når jeg forstår et nytt ord på bussen eller på jobb, blir jeg glad. Jeg vet at det tar tid å lære et språk, men hver uke forstår jeg litt mer.	Меня зовут Надя, и я учу норвежский. Я хожу на курсы норвежского два вечера в неделю. Наша учительница добрая и говорит медленно. Сначала мы вместе читаем небольшой текст, а потом разговариваем по двое. Иногда я боюсь сказать что‑то неправильно, но учительница говорит, что когда учишься, можно ошибаться. Дома я стараюсь каждый день хоть немного использовать норвежский. Я пишу список покупок по‑норвежски и говорю «takk», «unnskyld» и «ha det» людям в магазине. Когда я понимаю новое слово в автобусе или на работе, мне становится радостно. Я знаю, что выучить язык — это долго, но каждую неделю я понимаю чуть‑чуть больше.	["A1", "language", "learning", "norwegian", "course"]	t	2025-12-04 09:01:17.697964+00	2025-12-04 09:01:17.697978+00	Jeg heter Nadia, og jeg lærer norsk. Jeg går på norskkurs to kvelder i uka. Læreren vår er snill og snakker sakte. Først leser vi en liten tekst sammen, og etterpå snakker vi to og to. Noen ganger er jeg redd for å si feil, men læreren sier at det er lov å gjøre feil når man lærer. Hjemme prøver jeg å bruke litt norsk hver dag. Jeg skriver handleliste på norsk, og jeg sier «takk», «unnskyld» og «ha det» til folk i butikken. Når jeg forstår et nytt ord på bussen eller på jobb, blir jeg glad. Jeg vet at det tar tid å lære et språk, men hver uke forstår jeg litt mer.	Eg heiter Nadia, og eg lærer norsk. Eg går på norskkurs to kveldar i veka. Læraren vår er snill og snakkar sakte. Først les vi ein liten tekst saman, og etterpå snakkar vi to og to. Nokre gonger er eg redd for å seie feil, men læraren seier at det er lov å gjere feil når ein lærer. Heime prøver eg å bruke litt norsk kvar dag. Eg skriv handleliste på norsk, og eg seier «takk», «unnskyld» og «ha det» til folk i butikken. Når eg forstår eit nytt ord på bussen eller på jobb, blir eg glad. Eg veit at det tek tid å lære eit språk, men kvar veke forstår eg litt meir.	My name is Nadia, and I am learning Norwegian. I go to a Norwegian course two evenings a week. Our teacher is kind and speaks slowly. First we read a small text together, and afterwards we talk in pairs. Sometimes I am afraid to say something wrong, but the teacher says that it is allowed to make mistakes when you learn. At home I try to use a little Norwegian every day. I write my shopping list in Norwegian, and I say “takk”, “unnskyld” and “ha det” to people in the shop. When I understand a new word on the bus or at work, I become happy. I know that it takes time to learn a language, but every week I understand a little more.	I am learning Norwegian	Jeg lærer norsk	Eg lærer norsk	Я учу норвежский
33	Norsk i hverdagen	a2-bm-learning-norwegian	bokmaal	A2	Da jeg kom til Norge, trodde jeg at jeg bare lærte norsk på skolen. Etter noen måneder forsto jeg at jeg egentlig lærer språk hele tiden. På norskkurset får jeg grammatikk og lekser, men jeg lærer også mye på butikken, på jobb og når jeg henter barna i barnehagen. Jeg øver meg på å stille enkle spørsmål: «Kan du gjenta?», «Hva betyr det?» og «Hvordan skriver man det?» Hver kveld skriver jeg tre–fire korte setninger i en liten skrivebok om dagen min. Noen setninger blir rare, men det gjør ikke noe. Når jeg møter naboen ute, prøver jeg å si én setning mer enn sist gang. Noen dager er jeg sliten og har lyst til å snakke engelsk, men da tenker jeg at norsk er nøkkelen til å forstå samfunnet bedre. Det er ikke alltid gøy å øve, men det føles veldig fint når jeg plutselig forstår en hel beskjed fra skolen uten å bruke ordbok.	Когда я приехал в Норвегию, я думал, что учу норвежский только в школе. Через несколько месяцев я понял, что на самом деле учу язык всё время. На курсах норвежского я получаю грамматику и домашние задания, но многое учу и в магазине, и на работе, и когда забираю детей из детсада. Я тренируюсь задавать простые вопросы: «Kan du gjenta?» (можете повторить?), «Hva betyr det?» (что это значит?) и «Hvordan skriver man det?» (как это пишется?). Каждый вечер я пишу три–четыре коротких предложения в маленькой тетрадке о своём дне. Какие‑то предложения получаются странными, но это не страшно. Когда я встречаю соседа на улице, я стараюсь сказать на одно предложение больше, чем в прошлый раз. Иногда я устаю и хочу говорить по‑английски, но тогда думаю, что норвежский — это ключ к лучшему пониманию общества. Тренироваться не всегда весело, но очень приятно, когда вдруг понимаешь целое сообщение из школы без словаря.	["A2", "language", "learning", "daily", "practice"]	t	2025-12-04 09:01:17.703253+00	2025-12-04 09:01:17.703276+00	Da jeg kom til Norge, trodde jeg at jeg bare lærte norsk på skolen. Etter noen måneder forsto jeg at jeg egentlig lærer språk hele tiden. På norskkurset får jeg grammatikk og lekser, men jeg lærer også mye på butikken, på jobb og når jeg henter barna i barnehagen. Jeg øver meg på å stille enkle spørsmål: «Kan du gjenta?», «Hva betyr det?» og «Hvordan skriver man det?» Hver kveld skriver jeg tre–fire korte setninger i en liten skrivebok om dagen min. Noen setninger blir rare, men det gjør ikke noe. Når jeg møter naboen ute, prøver jeg å si én setning mer enn sist gang. Noen dager er jeg sliten og har lyst til å snakke engelsk, men da tenker jeg at norsk er nøkkelen til å forstå samfunnet bedre. Det er ikke alltid gøy å øve, men det føles veldig fint når jeg plutselig forstår en hel beskjed fra skolen uten å bruke ordbok.	Då eg kom til Noreg, trudde eg at eg berre lærte norsk på skulen. Etter nokre månader forsto eg at eg eigentleg lærer språk heile tida. På norskkurset får eg grammatikk og lekser, men eg lærer òg mykje i butikken, på jobb og når eg hentar barna i barnehagen. Eg øver meg på å stille enkle spørsmål: «Kan du gjenta?», «Kva tyder det?» og «Korleis skriv ein det?» Kvar kveld skriv eg tre–fire korte setningar i ei lita skrivebok om dagen min. Nokre setningar blir rare, men det gjer ingenting. Når eg møter naboen ute, prøver eg å seie ei setning meir enn sist gong. Nokre dagar er eg sliten og har lyst til å snakke engelsk, men då tenkjer eg at norsk er nøkkelen til å forstå samfunnet betre. Det er ikkje alltid gøy å øve, men det kjennest veldig godt når eg plutseleg forstår ei heil melding frå skulen utan å bruke ordbok.	When I came to Norway, I thought that I only learned Norwegian at school. After some months I understood that I actually learn the language all the time. At the Norwegian course I get grammar and homework, but I also learn a lot in the shop, at work and when I pick up the children in kindergarten. I practise asking simple questions: “Can you repeat?”, “What does that mean?” and “How do you spell that?” Every evening I write three or four short sentences in a small notebook about my day. Some sentences become strange, but that does not matter. When I meet the neighbour outside, I try to say one sentence more than last time. Some days I am tired and want to speak English, but then I think that Norwegian is the key to understanding society better. It is not always fun to practise, but it feels very good when I suddenly understand a whole message from the school without using a dictionary.	Norwegian in everyday life	Norsk i hverdagen	Norsk i kvardagen	Норвежский в повседневной жизни
34	Opp og ned med språket	b1-bm-learning-norwegian	bokmaal	B1	Å lære norsk har ikkje vore ei rett linje for meg, men meir som ein sti med både oppoverbakker og små pauser. Nokre veker føler eg at alt går framover: eg forstår meir på jobb, eg vågar å spøke litt på norsk, og eg finn faktisk riktige verbformer utan å tenkje for lenge. Andre veker er det som om språket stoppar opp. Eg blandar kjønn på substantiv, gløymer enkle ord og blir stille i samtalar fordi eg ikkje finn setninga eg vil seie. Før blei eg veldig skuffa dei dagane, men etter kvart har eg skjønt at slike periodar er ein del av læringa. No prøver eg å sjå etter små teikn på framgang, sjølv når eg er lei: at eg forstår meir av nyheitene på radio, at eg kan lese meldingar frå skulen raskare, eller at eg klarer å forklare ein feil på jobben utan å gå over til engelsk. Språket kjem ikkje av seg sjølv, men det kjem, litt og litt, kvar gong eg likevel opnar boka eller vågar å seie ei setning til.	Изучение норвежского для меня оказалось не прямой линией, а скорее тропинкой с подъёмами и маленькими остановками. Бывают недели, когда кажется, что всё идёт вперёд: я больше понимаю на работе, осмеливаюсь немного шутить по‑норвежски и даже нахожу правильные формы глагола, не думая слишком долго. В другие недели язык как будто останавливается. Я путаю род существительных, забываю простые слова и замолкаю в разговоре, потому что не могу собрать фразу, которую хочу сказать. Раньше в такие дни я сильно расстраивался, но со временем понял, что такие периоды — часть процесса. Сейчас я стараюсь замечать маленькие признаки прогресса, даже когда устал: что лучше понимаю новости по радио, быстрее читаю школьные сообщения или могу объяснить ошибку на работе, не переходя на английский. Язык не приходит сам по себе, но он всё‑таки приходит — понемногу, каждый раз, когда я всё же открываю учебник или решаю сказать ещё одно предложение.	["B1", "language", "learning", "motivation", "progress"]	t	2025-12-04 09:01:17.708607+00	2025-12-04 09:01:17.708622+00	Å lære norsk har ikkje vore ei rett linje for meg, men meir som ein sti med både oppoverbakker og små pauser. Nokre veker føler eg at alt går framover: eg forstår meir på jobb, eg vågar å spøke litt på norsk, og eg finn faktisk riktige verbformer utan å tenkje for lenge. Andre veker er det som om språket stoppar opp. Eg blandar kjønn på substantiv, gløymer enkle ord og blir stille i samtalar fordi eg ikkje finn setninga eg vil seie. Før blei eg veldig skuffa dei dagane, men etter kvart har eg skjønt at slike periodar er ein del av læringa. No prøver eg å sjå etter små teikn på framgang, sjølv når eg er lei: at eg forstår meir av nyheitene på radio, at eg kan lese meldingar frå skulen raskare, eller at eg klarer å forklare ein feil på jobben utan å gå over til engelsk. Språket kjem ikkje av seg sjølv, men det kjem, litt og litt, kvar gong eg likevel opnar boka eller vågar å seie ei setning til.	Å lære norsk har ikkje vore ei rett linje for meg, men meir som ein sti med både oppoverbakkar og små pausar. Nokre veker kjenner eg at alt går framover: eg forstår meir på jobb, eg vågar å spøke litt på norsk, og eg finn faktisk riktige verbformer utan å tenkje for lenge. Andre veker er det som om språket stoppar opp. Eg blandar kjønn på substantiv, gløymer enkle ord og blir stille i samtalar fordi eg ikkje finn setninga eg vil seie. Før blei eg veldig skuffa dei dagane, men etter kvart har eg skjønt at slike periodar er ein del av læringa. No prøver eg å sjå etter små teikn på framgang, sjølv når eg er lei: at eg forstår meir av nyheitene på radio, at eg kan lese meldingar frå skulen raskare, eller at eg klarer å forklare ein feil på jobben utan å gå over til engelsk. Språket kjem ikkje av seg sjølv, men det kjem, litt etter litt, kvar gong eg likevel opnar boka eller vågar å seie ei setning til.	Learning Norwegian has not been a straight line for me, but more like a path with both uphill climbs and small breaks. Some weeks I feel that everything is moving forward: I understand more at work, I dare to joke a little in Norwegian, and I actually find the correct verb forms without thinking for too long. Other weeks it is as if the language stops. I mix up the gender of nouns, forget simple words and become quiet in conversations because I cannot find the sentence I want to say. Before, I became very disappointed on those days, but gradually I have understood that such periods are part of learning. Now I try to look for small signs of progress, even when I am tired: that I understand more of the news on the radio, that I can read messages from the school faster, or that I manage to explain a mistake at work without switching to English. The language does not come by itself, but it does come, little by little, every time I still open the book or dare to say one more sentence.	Ups and downs with the language	Opp og ned med språket	Opp og ned med språket	Подъёмы и спады в языке
35	Språk som nøkkel til deltaking	b2-bm-learning-norwegian	bokmaal	B2	Etter fleire år i Noreg har eg forstått at norsk ikkje berre er eit fag eg «må» lære, men eit verktøy eg stadig kan bruke til meir. I starten var målet mitt å kunne klare kvardagen: handle, gå til legen, snakke litt med læraren til barna. No merkar eg at språket også gir meg moglegheit til å delta på ein annan måte. Når eg forstår e‑postar frå kommunen utan å oversette alt, kan eg faktisk meine noko om det som skjer der vi bur. På jobb kan eg stille kritiske spørsmål på møta, ikkje berre sitje og nikke. Samtidig kjenner eg at aksenten min og dei små feila ikkje forsvinn, og kanskje kjem dei aldri til å gjere det. I staden for å skamme meg over det, øver eg meg på å vere tydeleg: seie frå når eg ikkje forstår, be andre snakke litt saktare, og likevel halde fram med å bruke norsk, sjølv om setningane mine ikkje alltid er perfekte. For meg har det blitt ei viktig innsikt at språket ikkje treng å vere feilfritt for å vere nyttig. Det viktigaste er at eg tør å bruke det, slik at eg kan vere med og påverke mitt eige liv her i landet.	После нескольких лет в Норвегии я понял, что норвежский — это не просто предмет, который я «должен» выучить, а инструмент, который я могу всё шире использовать. Сначала моя цель была просто справляться с бытом: сделать покупки, сходить к врачу, немного поговорить с учителем детей. Теперь я замечаю, что язык даёт мне возможность участвовать по‑другому. Когда я понимаю письма от коммуны, не переводя каждое слово, я действительно могу иметь своё мнение о том, что происходит там, где мы живём. На работе я могу задавать критические вопросы на совещаниях, а не только сидеть и кивать. В то же время я чувствую, что мой акцент и маленькие ошибки никуда не исчезают, и, возможно, никогда и не исчезнут. Вместо того чтобы стыдиться этого, я тренируюсь быть понятным: говорить, когда я чего‑то не понимаю, просить других говорить чуть медленнее и всё равно продолжать использовать норвежский, даже если мои предложения не всегда идеальны. Для меня стало важным понимание: язык не обязан быть безошибочным, чтобы быть полезным. Главное — чтобы я не боялся его использовать и мог участвовать и влиять на свою жизнь здесь, в этой стране.	["B2", "language", "learning", "participation", "society"]	t	2025-12-04 09:01:17.718154+00	2025-12-04 09:01:17.718171+00	Etter fleire år i Noreg har eg forstått at norsk ikkje berre er eit fag eg «må» lære, men eit verktøy eg stadig kan bruke til meir. I starten var målet mitt å kunne klare kvardagen: handle, gå til legen, snakke litt med læraren til barna. No merkar eg at språket også gir meg moglegheit til å delta på ein annan måte. Når eg forstår e‑postar frå kommunen utan å oversette alt, kan eg faktisk meine noko om det som skjer der vi bur. På jobb kan eg stille kritiske spørsmål på møta, ikkje berre sitje og nikke. Samtidig kjenner eg at aksenten min og dei små feila ikkje forsvinn, og kanskje kjem dei aldri til å gjere det. I staden for å skamme meg over det, øver eg meg på å vere tydeleg: seie frå når eg ikkje forstår, be andre snakke litt saktare, og likevel halde fram med å bruke norsk, sjølv om setningane mine ikkje alltid er perfekte. For meg har det blitt ei viktig innsikt at språket ikkje treng å vere feilfritt for å vere nyttig. Det viktigaste er at eg tør å bruke det, slik at eg kan vere med og påverke mitt eige liv her i landet.	Etter fleire år i Noreg har eg forstått at norsk ikkje berre er eit fag eg «må» lære, men eit verktøy eg kan bruke til stadig meir. I starten var målet mitt å klare kvardagen: handle, gå til legen, snakke litt med læraren til barna. No merkar eg at språket òg gir meg moglegheit til å delta på ein annan måte. Når eg forstår e‑postar frå kommunen utan å omsetje alt, kan eg faktisk meine noko om det som skjer der vi bur. På jobb kan eg stille kritiske spørsmål i møta, ikkje berre sitje og nikke. Samstundes kjenner eg at aksenten min og dei små feila ikkje forsvinn, og kanskje kjem dei aldri til å gjere det. I staden for å skamme meg over det, øver eg meg på å vere tydeleg: seie frå når eg ikkje forstår, be andre snakke litt saktare, og likevel halde fram med å bruke norsk, sjølv om setningane mine ikkje alltid er perfekte. For meg har det blitt ei viktig innsikt at språket ikkje treng å vere feilfritt for å vere nyttig. Det viktigaste er at eg tør å bruke det, slik at eg kan vere med og påverke mitt eige liv her i landet.	After several years in Norway, I have realised that Norwegian is not just a subject I “have to” learn, but a tool that I can constantly use for more. At the beginning my goal was to manage everyday life: shopping, going to the doctor, talking a little with the children’s teacher. Now I notice that the language also gives me the possibility to participate in a different way. When I understand emails from the municipality without translating everything, I can actually have an opinion about what happens where we live. At work I can ask critical questions in meetings, not only sit and nod. At the same time I feel that my accent and the small mistakes do not disappear, and maybe they never will. Instead of being ashamed of that, I practise being clear: saying when I do not understand, asking others to speak a bit more slowly, and still continuing to use Norwegian even if my sentences are not always perfect. For me it has become an important insight that the language does not have to be without mistakes in order to be useful. The most important thing is that I dare to use it, so that I can take part and influence my own life here in this country.	Language as a key to participation	Språk som nøkkel til deltaking	Språk som nøkkel til deltaking	Язык как ключ к участию
19	Butikken som møteplass	b2-bm-grocery-shopping	bokmaal	B2	Etter nokre år i Noreg har eg oppdaga at matbutikken er meir enn ein stad der vi fyller handlekorga. I nærbutikken min ser eg nesten alltid nokon eg kjenner litt: ein nabo, ein kollega eller ein forelder frå skulen. Mellom hyllene blir det små samtalar om veret, fotballkampen i helga eller prisane på straum og mat. Samtidig er butikken full av val som seier noko om samfunnet vi lever i. Ein heil vegg med ferdigmiddagar står ved sida av hylla med tørre bønner og linser. Sukkerfri brus konkurrerer med juice og vatn med smak. Eg merkar ofte at eg står og veg mellom det raske og det som krev litt meir tid heime på kjøkkenet. For ein som lærer språk, er butikken òg ein gratis lærebok: etikettar, tilbodsplakatar og små lappar med «lokal mat» og «kortreist». Når eg går heim med posane mine, tenkjer eg av og til på korleis desse kvardagslege vala – kva vi legg i korga, kven vi helsar på, og kva vi snakkar om – faktisk formar både helsa og fellesskapet vårt, litt og litt, kvar einaste dag.	После нескольких лет в Норвегии я заметил, что продуктовый магазин — это не только место, где мы наполняем тележку. В моём ближайшем магазине я почти всегда встречаю кого-то, кого немного знаю: соседа, коллегу или родителя из школы. Между полками возникают короткие разговоры о погоде, футбольном матче в выходные или ценах на электричество и продукты. В то же время магазин полон выборов, которые что-то говорят о нашем обществе. Целая стена готовых ужинов стоит рядом с полкой с сухой фасолью и чечевицей. Безсахарная газировка конкурирует с соком и водой со вкусом. Я часто ловлю себя на том, что стою и выбираю между быстрым вариантом и тем, что требует немного больше времени дома на кухне. Для человека, который учит язык, магазин — это ещё и бесплатный учебник: этикетки, плакаты с акциями и маленькие таблички с надписями «lokal mat» и «kortreist». Когда я иду домой с пакетами, я иногда думаю о том, как эти повседневные выборы — что мы кладём в корзину, с кем здороваемся и о чём говорим — на самом деле формируют и наше здоровье, и наше сообщество, понемногу, каждый день.	["B2", "society", "shopping", "community"]	t	2025-12-03 09:15:51.61481+00	2025-12-04 11:04:43.805964+00	Etter noen år i Norge har jeg oppdaget at matbutikken er mer enn et sted der vi fyller handlevogna. I nærbutikken min ser jeg nesten alltid noen jeg kjenner litt: en nabo, en kollega eller en forelder fra skolen. Mellom hyllene blir det små samtaler om været, fotballkampen i helga eller prisene på strøm og mat. Samtidig er butikken full av valg som sier noe om samfunnet vi lever i. En hel vegg med ferdigmiddager står ved siden av hylla med tørre bønner og linser. Sukkerfri brus konkurrerer med juice og vann med smak. Jeg merker ofte at jeg står og vipper mellom det som går raskt, og det som krever litt mer tid hjemme på kjøkkenet. For en som lærer språk, er butikken også en gratis lærebok: etiketter, tilbudsplakater og små lapper med «lokal mat» og «kortreist». Når jeg går hjem med posene mine, tenker jeg av og til på hvordan disse hverdagslige valgene – hva vi legger i vogna, hvem vi hilser på, og hva vi snakker om – faktisk former både helsa og fellesskapet vårt, litt etter litt, hver eneste dag.	Etter nokre år i Noreg har eg oppdaga at matbutikken er meir enn ein stad der vi fyller handlekorga. I nærbutikken min ser eg nesten alltid nokon eg kjenner litt: ein nabo, ein kollega eller ein forelder frå skulen. Mellom hyllene blir det små samtalar om vêret, fotballkampen i helga eller prisane på straum og mat. Samstundes er butikken full av val som seier noko om samfunnet vi lever i. Ein heil vegg med ferdigmiddagar står ved sida av hylla med tørre bønner og linser. Sukkerfri brus konkurrerer med juice og vatn med smak. Eg merkar ofte at eg står og veg mellom det raske alternativet og det som krev litt meir tid heime på kjøkkenet. For ein som lærer språk, er butikken òg ei gratis lærebok: etikettar, tilbodsplakatar og små lappar med «lokal mat» og «kortreist». Når eg går heim med posane mine, tenkjer eg av og til på korleis desse kvardagslege vala – kva vi legg i korga, kven vi helsar på, og kva vi snakkar om – faktisk formar både helsa og fellesskapet vårt, litt etter litt, kvar einaste dag.	After a few years in Norway, I have discovered that the grocery store is more than a place where we fill our shopping basket. In my local shop I almost always see someone I know a little: a neighbour, a colleague or a parent from school. Between the shelves there are small conversations about the weather, the football match at the weekend, or the prices of electricity and food. At the same time the shop is full of choices that say something about the society we live in. A whole wall of ready-made dinners stands next to the shelf with dried beans and lentils. Sugar-free soft drinks compete with juice and flavoured water. I often notice that I stand and weigh up between the quick option and what demands a little more time at home in the kitchen. For someone who is learning the language, the shop is also a free textbook: labels, special offer posters and small notes with “local food” and “short travelled”. When I walk home with my bags, I sometimes think about how these everyday choices – what we put in the basket, whom we greet, and what we talk about – actually shape both our health and our community, little by little, every single day.	The grocery store as meeting place	Butikken som møteplass	Butikken som møteplass	Магазин как место встречи
36	Jeg kjøper avis	a1-bm-world-news	bokmaal	A1	Jeg heter Omar, og jeg liker å lese nyheter. I dag kjøper jeg en avis på butikken før jeg går på jobb. Utenfor er det kaldt, og jeg har hansker på. Inne i avisa er det mange bilder og korte tekster. På første side ser jeg et stort bilde av jorda sett fra rommet. Under bildet står det at mange land skal møtes for å snakke om klima og vær. På en annen side er det en sak om fotball. Et lag fra Norge har vunnet en viktig kamp. Jeg leser litt, tar en slurk kaffe og føler at jeg forstår litt mer av hva som skjer i verden. Selv om jeg ikke forstår alle ordene, prøver jeg å lese høyt noen setninger for å øve på norsk.	Меня зовут Омар, и я люблю читать новости. Сегодня я покупаю газету в магазине перед работой. На улице холодно, на мне перчатки. Внутри газеты много картинок и коротких текстов. На первой странице я вижу большое фото Земли из космоса. Под фото написано, что многие страны встретятся, чтобы говорить о климате и погоде. На другой странице — статья о футболе. Одна норвежская команда выиграла важный матч. Я немного читаю, делаю глоток кофе и чувствую, что понимаю чуть больше о том, что происходит в мире. Хотя я не понимаю все слова, я пробую читать вслух несколько предложений, чтобы тренировать норвежский.	["A1", "news", "newspaper", "daily", "reading"]	t	2025-12-04 12:07:53.018004+00	2025-12-04 12:07:53.018023+00	Jeg heter Omar, og jeg liker å lese nyheter. I dag kjøper jeg en avis på butikken før jeg går på jobb. Utenfor er det kaldt, og jeg har hansker på. Inne i avisa er det mange bilder og korte tekster. På første side ser jeg et stort bilde av jorda sett fra rommet. Under bildet står det at mange land skal møtes for å snakke om klima og vær. På en annen side er det en sak om fotball. Et lag fra Norge har vunnet en viktig kamp. Jeg leser litt, tar en slurk kaffe og føler at jeg forstår litt mer av hva som skjer i verden. Selv om jeg ikke forstår alle ordene, prøver jeg å lese høyt noen setninger for å øve på norsk.	Eg heiter Omar, og eg liker å lese nyheiter. I dag kjøper eg ei avis på butikken før eg går på jobb. Ute er det kaldt, og eg har hanskar på. Inne i avisa er det mange bilete og korte tekstar. På første sida ser eg eit stort bilete av jorda sett frå verdsrommet. Under biletet står det at mange land skal møtast for å snakke om klima og vêr. På ei anna side er det ei sak om fotball. Eit lag frå Noreg har vunne ein viktig kamp. Eg les litt, tek ein slurk kaffe og kjenner at eg forstår litt meir av kva som skjer i verda. Sjølv om eg ikkje forstår alle orda, prøver eg å lese nokre setningar høgt for å øve på norsk.	My name is Omar, and I like to read the news. Today I buy a newspaper in the shop before I go to work. Outside it is cold, and I am wearing gloves. Inside the newspaper there are many pictures and short texts. On the first page I see a big picture of the Earth seen from space. Under the picture it says that many countries will meet to talk about climate and weather. On another page there is a story about football. A team from Norway has won an important match. I read a little, take a sip of coffee and feel that I understand a bit more of what is happening in the world. Even though I do not understand all the words, I try to read some sentences aloud to practise Norwegian.	I buy a newspaper	Jeg kjøper avis	Eg kjøper avis	Я покупаю газету
37	Verdensnyheter ved kjøkkenbordet	a2-bm-world-news	bokmaal	A2	Hver lørdag kjøper jeg papiravis i kiosken på hjørnet. Det er litt gammeldags, men jeg liker lyden av papir og lukten av trykksverte. Jeg setter meg ved kjøkkenbordet, folder ut avisa og begynner på forsiden. Der står det om et stort møte mellom lederne i flere land. De diskuterer krig, fred og hvordan de kan samarbeide bedre. Litt lenger bak i avisa finner jeg en artikkel om et jordskjelv i et annet land. Mange hus er ødelagt, og mennesker trenger hjelp. På en egen side står det positive nyheter: forskere har funnet en ny type medisin, og et lite land har bygd flere skoler for barn. Når jeg leser, prøver jeg å merke hvilke ord jeg forstår, og hvilke jeg må slå opp. Jeg legger avisa i sekken og tar den med på bussen, så jeg kan lese litt til på vei til jobb.	Каждую субботу я покупаю бумажную газету в киоске на углу. Это немного по-старому, но мне нравится звук бумаги и запах типографской краски. Я сажусь за кухонный стол, разворачиваю газету и начинаю с первой страницы. Там написано о большой встрече лидеров нескольких стран. Они обсуждают войну, мир и то, как им лучше сотрудничать. Чуть дальше в газете я нахожу статью о землетрясении в другой стране. Многие дома разрушены, людям нужна помощь. На отдельной странице — позитивные новости: учёные нашли новый вид лекарства, а в маленькой стране построили больше школ для детей. Когда я читаю, стараюсь замечать, какие слова я понимаю, а какие нужно посмотреть в словаре. Я кладу газету в рюкзак и беру её с собой в автобус, чтобы почитать ещё по дороге на работу.	["A2", "news", "newspaper", "world", "reading"]	t	2025-12-04 12:07:53.025815+00	2025-12-04 12:07:53.025833+00	Hver lørdag kjøper jeg papiravis i kiosken på hjørnet. Det er litt gammeldags, men jeg liker lyden av papir og lukten av trykksverte. Jeg setter meg ved kjøkkenbordet, folder ut avisa og begynner på forsiden. Der står det om et stort møte mellom lederne i flere land. De diskuterer krig, fred og hvordan de kan samarbeide bedre. Litt lenger bak i avisa finner jeg en artikkel om et jordskjelv i et annet land. Mange hus er ødelagt, og mennesker trenger hjelp. På en egen side står det positive nyheter: forskere har funnet en ny type medisin, og et lite land har bygd flere skoler for barn. Når jeg leser, prøver jeg å merke hvilke ord jeg forstår, og hvilke jeg må slå opp. Jeg legger avisa i sekken og tar den med på bussen, så jeg kan lese litt til på vei til jobb.	Kvar laurdag kjøper eg papiravis i kiosken på hjørnet. Det er litt gammaldags, men eg liker lyden av papir og lukta av trykksverte. Eg set meg ved kjøkenbordet, brettar ut avisa og begynner på framsida. Der står det om eit stort møte mellom leiarane i fleire land. Dei diskuterer krig, fred og korleis dei kan samarbeide betre. Litt lenger bak i avisa finn eg ein artikkel om eit jordskjelv i eit anna land. Mange hus er øydelagde, og menneske treng hjelp. På ei eiga side står det positive nyheiter: forskarar har funne ein ny type medisin, og eit lite land har bygd fleire skular for barn. Når eg les, prøver eg å leggje merke til kva ord eg forstår, og kva eg må slå opp. Eg legg avisa i sekken og tek ho med på bussen, slik at eg kan lese litt til på veg til jobb.	Every Saturday I buy a paper newspaper at the kiosk on the corner. It is a bit old-fashioned, but I like the sound of paper and the smell of ink. I sit down at the kitchen table, open the newspaper and start on the front page. There it says about a big meeting between leaders in several countries. They discuss war, peace and how they can cooperate better. A bit further back in the newspaper I find an article about an earthquake in another country. Many houses are destroyed, and people need help. On a special page there is positive news: researchers have found a new type of medicine, and a small country has built more schools for children. When I read, I try to notice which words I understand and which I have to look up. I put the newspaper in my bag and take it with me on the bus so I can read a bit more on the way to work.	World news at the kitchen table	Verdensnyheter ved kjøkkenbordet	Verdsnyheiter ved kjøkenbordet	Мировые новости за кухонным столом
38	Å lese om verda	b1-bm-world-news	bokmaal	B1	Noen kvelder bestemmer jeg meg for å legge mobilen bort og heller ta fram papiravisa som ligger på stuebordet. Når jeg blar gjennom sidene med verdensnyheter, får jeg et lite glimt inn i mange liv som er helt annerledes enn mitt. På én side skriver de om flom og tørke, på en annen om nye valg i et land jeg nesten aldri har hørt om. Jeg merker at det er lett å bli litt trist og sliten av alle de alvorlige sakene. Samtidig liker jeg at avisa også har små reportasjer om mennesker som prøver å gjøre en forskjell: ei ung jente som starter miljøprosjekt på skolen sin, eller frivillige som reiser til katastrofeområder for å hjelpe. Når jeg legger avisa fra meg, tenker jeg ofte på korleis nyhetene påverkar måten eg ser verda på. Eg kan ikkje gjere noko med alt som skjer, men eg kan i alle fall vere meir bevisst når eg stemmer, når eg bruker pengar, og når eg møter menneske frå andre land i kvardagen min.	Иногда вечером я решаю отложить телефон и вместо этого взять бумажную газету, которая лежит на журнальном столике. Листая страницы с мировыми новостями, я получаю маленький взгляд в чужие жизни, совсем не похожие на мою. На одной полосе пишут о наводнениях и засухе, на другой — о новых выборах в стране, о которой я почти ничего не слышал. Я замечаю, что от всех этих серьёзных новостей легко стать грустным и уставшим. В то же время мне нравится, что в газете есть небольшие репортажи о людях, которые стараются что-то изменить: юная девушка, которая запускает экологический проект в своей школе, или волонтёры, которые едут в районы бедствий помогать. Когда я откладываю газету, я часто думаю о том, как новости влияют на то, как я вижу мир. Я не могу повлиять на всё, что происходит, но, по крайней мере, могу быть более осознанным, когда голосую, трачу деньги и встречаю людей из других стран в своей повседневной жизни.	["B1", "news", "world", "reflection", "everyday"]	t	2025-12-04 12:07:53.033971+00	2025-12-04 12:07:53.033986+00	Noen 