 many lives that are completely different from my own. On one page they write about floods and droughts, on another about new elections in a country I have hardly ever heard of. I notice that it is easy to become a bit sad and tired from all the serious stories. At the same time I like that the newspaper also has small reports about people who try to make a difference: a young girl who starts an environmental project at her school, or volunteers who travel to disaster areas to help. When I put the newspaper down, I often think about how the news influences the way I see the world. I cannot do anything about everything that happens, but at least I can be more conscious when I vote, when I spend money, and when I meet people from other countries in my everyday life.	Reading about the world	Å lese om verden	Å lese om verda	Читать о мире
39	Kritisk blikk på nyhetene	b2-bm-world-news	bokmaal	B2	Når eg sit med ei papiravis og les verdsnyheiter, merkar eg kor annleis det kjennest enn å bla raskt gjennom overskrifter på mobilen. I avisa må eg velje: skal eg bruke fem minutt på å lese denne lange analysen om økonomisk krise i eit anna kontinent, eller hoppar eg vidare til sportssidene? Mange av sakene er skrivne langt borte frå livet mitt, men påverkar likevel kvardagen min gjennom straumprisar, politiske avgjerder eller klimaendringar. Samtidig veit eg at kvar artikkel berre viser ein liten bit av røynda. Kva for land og konfliktar får plass på første sida, og kven blir nesten aldri nemnd? Kven sit med makta til å formulere historia om «verda»? Desse spørsmåla gjer meg ikkje mindre interessert i nyheiter, men dei gjer at eg les meir kritisk. Eg prøver å sjekke fleire kjelder, og eg minner meg sjølv på at menneska i artiklane ikkje berre er tal og kart, men enkeltpersonar med kvardag, familie og draumar. Kanskje er ikkje det viktigaste at eg kan alt om alle konfliktar, men at eg let nyheitene utfordre både haldningane og vala mine – også etter at eg har bretta saman avisa og lagt henne tilbake på bordet.	Когда я сижу с бумажной газетой и читаю мировые новости, я чувствую, насколько это отличается от быстрого пролистывания заголовков в телефоне. В газете мне приходится выбирать: потратить ли пять минут на длинный разбор экономического кризиса на другом континенте или перелистнуть сразу к разделу спорта. Многие материалы написаны о местах, которые далеко от моей жизни, но всё равно влияют на мой быт — через цены на электричество, политические решения или изменения климата. В то же время я понимаю, что каждая статья показывает только маленький кусочек реальности. Какие страны и конфликты попадают на первую полосу, а кого почти никогда не упоминают? У кого есть власть формулировать историю о том, что такое «мир»? Эти вопросы не уменьшают мой интерес к новостям, но делают чтение более критичным. Я стараюсь смотреть несколько источников и напоминаю себе, что люди в статьях — это не только цифры и карты, а отдельные личности с повседневной жизнью, семьями и мечтами. Может быть, самое важное не в том, чтобы знать всё обо всех конфликтах, а в том, чтобы позволить новостям задать вопросы к моим взглядам и выбору — даже после того, как я сложил газету и положил её обратно на стол.	["B2", "news", "world", "media", "critical", "reflection"]	t	2025-12-04 12:07:53.03892+00	2025-12-04 12:07:53.038931+00	Når eg sit med ei papiravis og les verdsnyheiter, merkar eg kor annleis det kjennest enn å bla raskt gjennom overskrifter på mobilen. I avisa må eg velje: skal eg bruke fem minutt på å lese denne lange analysen om økonomisk krise i eit anna kontinent, eller hoppar eg vidare til sportssidene? Mange av sakene er skrivne langt borte frå livet mitt, men påverkar likevel kvardagen min gjennom straumprisar, politiske avgjerder eller klimaendringar. Samtidig veit eg at kvar artikkel berre viser ein liten bit av røynda. Kva for land og konfliktar får plass på første sida, og kven blir nesten aldri nemnd? Kven sit med makta til å formulere historia om «verda»? Desse spørsmåla gjer meg ikkje mindre interessert i nyheiter, men dei gjer at eg les meir kritisk. Eg prøver å sjekke fleire kjelder, og eg minner meg sjølv på at menneska i artiklane ikkje berre er tal og kart, men enkeltpersonar med kvardag, familie og draumar. Kanskje er ikkje det viktigaste at eg kan alt om alle konfliktar, men at eg let nyheitene utfordre både haldningane og vala mine – også etter at eg har bretta saman avisa og lagt henne tilbake på bordet.	Når eg sit med ei papiravis og les verdsnyheiter, merkar eg kor annleis det kjennest enn å bla raskt gjennom overskrifter på mobilen. I avisa må eg velje: skal eg bruke fem minutt på å lese denne lange analysen om økonomisk krise på eit anna kontinent, eller hoppar eg vidare til sportssidene? Mange av sakene er skrivne langt borte frå livet mitt, men påverkar likevel kvardagen min gjennom straumprisar, politiske vedtak eller klimaendringar. Samstundes veit eg at kvar artikkel berre viser ein liten bit av røynda. Kva for land og konfliktar får plass på framsida, og kven blir nesten aldri nemnd? Kven sit med makta til å formulere historia om «verda»? Desse spørsmåla gjer meg ikkje mindre interessert i nyheiter, men dei gjer at eg les meir kritisk. Eg prøver å sjekke fleire kjelder, og eg minner meg sjølv på at menneska i artiklane ikkje berre er tal og kart, men enkeltpersonar med kvardag, familie og draumar. Kanskje er ikkje det viktigaste at eg kan alt om alle konfliktar, men at eg let nyheitene utfordre både haldningane og vala mine – også etter at eg har bretta saman avisa og lagt henne tilbake på bordet.	When I sit with a paper newspaper and read world news, I notice how different it feels from quickly scrolling through headlines on my phone. In the newspaper I have to choose: shall I spend five minutes reading this long analysis about an economic crisis on another continent, or jump on to the sports pages? Many of the stories are written far away from my own life, but still affect my everyday life through electricity prices, political decisions or climate change. At the same time I know that each article only shows a small part of reality. Which countries and conflicts get space on the front page, and who is almost never mentioned? Who has the power to formulate the story about “the world”? These questions do not make me less interested in the news, but they make me read more critically. I try to check several sources, and I remind myself that the people in the articles are not only numbers and maps, but individuals with everyday lives, families and dreams. Perhaps the most important thing is not that I know everything about every conflict, but that I let the news challenge both my attitudes and my choices – also after I have folded the newspaper and put it back on the table.	A critical look at the news	Kritisk blikk på nyhetene	Kritisk blikk på nyheitene	Критический взгляд на новости
196	Mekaniker på linja	a1-bm-line-mechanic-duties	bokmaal	A1	Jeg heter Leo, og jeg jobber som mekaniker på en produksjonslinje. Hver morgen går jeg gjennom hallen før maskinene starter. Jeg ser om det ligger noe på gulvet, og om alle verneskjermer er på plass. Jeg sjekker olje på en motor, smører et lite kjede og tørker bort søl rundt maskinen. Når operatøren sier at han hører en rar lyd, går jeg bort og lytter. I dag knirker et lite hjul på transportbåndet. Vi stopper linja, slår av strømmen og låser bryteren. Jeg tar fram nøkkel og skrutrekker, strammer skruene og sprayer litt fett på hjulet. Etterpå starter vi linja igjen, og lyden er borte. Operatøren viser tommel opp, og vi fortsetter dagen.	Меня зовут Лео, и я работаю механиком на производственной линии. Каждое утро я прохожу по цеху до запуска станков. Я смотрю, не лежит ли что-то на полу и стоят ли все защитные кожухи на месте. Проверяю масло на одном моторе, смазываю маленькую цепь и вытираю потёки вокруг станка. Когда оператор говорит, что слышит странный звук, я подхожу и прислушиваюсь. Сегодня поскрипывает маленький ролик на транспортере. Мы останавливаем линию, выключаем питание и блокируем выключатель. Я беру ключ и отвёртку, подтягиваю винты и брызгаю немного смазки на ролик. Потом снова запускаем линию, и звук исчезает. Оператор показывает «лайк» пальцем, и мы продолжаем работу.	["A1", "work", "mechanic", "production-line", "duties", "small-repair"]	t	2025-12-08 14:19:25.564913+00	2025-12-08 14:19:25.564944+00	Jeg heter Leo, og jeg jobber som mekaniker på en produksjonslinje. Hver morgen går jeg gjennom hallen før maskinene starter. Jeg ser om det ligger noe på gulvet, og om alle verneskjermer er på plass. Jeg sjekker olje på en motor, smører et lite kjede og tørker bort søl rundt maskinen. Når operatøren sier at han hører en rar lyd, går jeg bort og lytter. I dag knirker et lite hjul på transportbåndet. Vi stopper linja, slår av strømmen og låser bryteren. Jeg tar fram nøkkel og skrutrekker, strammer skruene og sprayer litt fett på hjulet. Etterpå starter vi linja igjen, og lyden er borte. Operatøren viser tommel opp, og vi fortsetter dagen.	Eg heiter Leo, og eg jobbar som mekanikar på ei produksjonsline. Kvar morgon går eg gjennom hallen før maskinene startar. Eg ser om det ligg noko på golvet, og om alle verneskjermar er på plass. Eg sjekkar olje på ein motor, smører ei lita kjede og tørkar bort søl rundt maskina. Når operatøren seier at han høyrer ein rar lyd, går eg bort og lyttar. I dag knirkar eit lite hjul på transportbandet. Vi stoppar lina, slår av straumen og låser brytaren. Eg tek fram nøkkel og skrutrekker, strammar skruene og sprayar litt feitt på hjulet. Etterpå startar vi lina igjen, og lyden er borte. Operatøren viser tommel opp, og vi held fram med dagen.	My name is Leo, and I work as a mechanic on a production line. Every morning I walk through the hall before the machines start. I check if there is anything on the floor and if all safety covers are in place. I check the oil on a motor, grease a small chain and wipe up spills around the machine. When the operator says he hears a strange sound, I go over and listen. Today a small wheel on the conveyor is squeaking. We stop the line, turn off the power and lock the switch. I take out a spanner and a screwdriver, tighten the screws and spray some grease on the wheel. Afterwards we start the line again, and the sound is gone. The operator gives a thumbs up, and we continue the day.	Mechanic on the line	Mekaniker på linja	Mekanikar på lina	Механик на линии
197	Faste oppgaver på skiftet	a2-bm-line-mechanic-duties	bokmaal	A2	Som mekaniker på produksjonslinja har jeg faste oppgaver hver vakt. Først går jeg gjennom sjekklista på tavla: smøring, visuell kontroll og kort test av nødstopp. Jeg skriver dato og signatur når jeg er ferdig. I løpet av dagen ringer operatørene hvis noe ikke fungerer som vanlig. I dag stopper en sensor på pakkelinja å registrere esker. Operatøren sier at lyset på sensoren blinker rødt. Vi stopper linja og låser strømmen. Jeg rengjør sensoren med en myk klut og ser at den peker litt feil. Med en liten umbrakonøkkel løsner jeg skruen og justerer vinkelen slik at sensoren «ser» eskene igjen. Etter en test på lav hastighet går linja som normalt. Jeg skriver en kort beskjed i loggboka, så neste skift vet hva som har skjedd, og hva vi har gjort.	Как механик на производственной линии, я выполняю одни и те же обязанности в каждую смену. Сначала прохожу чек-лист на доске: смазка, визуальный осмотр и короткое тестирование аварийной остановки. В конце ставлю дату и свою подпись. В течение дня операторы звонят, если что-то работает не как обычно. Сегодня датчик на упаковочной линии перестал замечать коробки. Оператор говорит, что лампочка на датчике мигает красным. Мы останавливаем линию и блокируем питание. Я аккуратно чищу датчик мягкой тряпкой и вижу, что он немного повернут не в ту сторону. Маленьким шестигранником ослабляю винт и регулирую угол так, чтобы датчик снова «видел» коробки. После теста на низкой скорости линия идёт как обычно. Я пишу короткое сообщение в журнале, чтобы следующая смена знала, что произошло и что мы сделали.	["A2", "work", "mechanic", "production-line", "duties", "sensor-repair"]	t	2025-12-08 14:19:25.573789+00	2025-12-08 14:19:25.573807+00	Som mekaniker på produksjonslinja har jeg faste oppgaver hver vakt. Først går jeg gjennom sjekklista på tavla: smøring, visuell kontroll og kort test av nødstopp. Jeg skriver dato og signatur når jeg er ferdig. I løpet av dagen ringer operatørene hvis noe ikke fungerer som vanlig. I dag stopper en sensor på pakkelinja å registrere esker. Operatøren sier at lyset på sensoren blinker rødt. Vi stopper linja og låser strømmen. Jeg rengjør sensoren med en myk klut og ser at den peker litt feil. Med en liten umbrakonøkkel løsner jeg skruen og justerer vinkelen slik at sensoren «ser» eskene igjen. Etter en test på lav hastighet går linja som normalt. Jeg skriver en kort beskjed i loggboka, så neste skift vet hva som har skjedd, og hva vi har gjort.	Som mekanikar på produksjonslina har eg faste oppgåver kvar vakt. Først går eg gjennom sjekklista på tavla: smøring, visuell kontroll og ein kort test av naudstopp. Eg skriv dato og signatur når eg er ferdig. I løpet av dagen ringer operatørane dersom noko ikkje fungerer som vanleg. I dag sluttar ein sensor på pakkelina å registrere eskene. Operatøren seier at lyset på sensoren blinkar raudt. Vi stoppar lina og låser straumen. Eg reingjer sensoren med ein mjuk klut og ser at han peikar litt feil. Med ein liten umbrakonøkkel løyser eg skruen og justerer vinkelen slik at sensoren «ser» eskene igjen. Etter ein test på låg hastigheit går lina som normalt. Eg skriv ei kort melding i loggboka, slik at neste skift veit kva som har skjedd, og kva vi har gjort.	As a mechanic on the production line I have fixed tasks every shift. First I go through the checklist on the board: lubrication, visual inspection and a short test of the emergency stop. I write the date and my signature when I am finished. During the day the operators call if something does not work as usual. Today a sensor on the packing line stops registering boxes. The operator says that the light on the sensor is blinking red. We stop the line and lock the power. I clean the sensor with a soft cloth and see that it is pointing a bit wrong. With a small Allen key I loosen the screw and adjust the angle so that the sensor “sees” the boxes again. After a test at low speed, the line runs as normal. I write a short message in the logbook so the next shift knows what has happened and what we have done.	Fixed tasks on the shift	Faste oppgaver på skiftet	Faste oppgåver på skiftet	Постоянные обязанности в смену
198	Rolle på produksjonslinja	b1-bm-line-mechanic-duties	bokmaal	B1	På produksjonslinja der jeg jobber, er jeg ofte den første mekanikeren operatørene ringer til når noe skjer. Jeg kjenner maskinene godt, fordi jeg både gjør daglig vedlikehold og har vært med på flere større reparasjoner. En vanlig dag handler mye om små ting: skru fast løse deksler, bytte en slitt gummilist eller justere et bånd som går litt skeivt. Men noen ganger må vi stoppe hele linja for å finne en mer alvorlig feil. Forrige måned begynte en av drivstasjonene å lage høy, metallisk lyd. I stedet for å bare skru opp volumet på radioen, ba jeg operatøren stoppe linja. Sammen sjekket vi kjede, tannhjul og lager. Det viste seg at ett lager var nesten tørt for fett. Vi demonterte dekselet, renset området og smurte opp på nytt. I rapporten skrev jeg ikke bare hva vi hadde gjort, men også et forslag om å legge inn ekstra smørepunkter i vedlikeholdsplanen. Slik prøver jeg å tenke både på dagens stopp og på hvordan vi kan unngå det neste.	На производственной линии, где я работаю, я часто тот механик, которому операторы звонят первым, когда что‑то случается. Я хорошо знаю оборудование, потому что делаю ежедневное обслуживание и участвовал уже во многих крупных ремонтах. Обычный день – это в основном мелочи: подтянуть ослабший кожух, заменить изношенный резиновый уплотнитель, подправить ленту, которая идёт немного криво. Но иногда приходится останавливать всю линию, чтобы найти более серьёзную неисправность. В прошлом месяце один из приводов начал издавать громкий металлический звук. Вместо того чтобы просто сделать радио погромче, я попросил оператора полностью остановить линию. Мы вместе проверили цепь, шестерни и подшипники. Оказалось, что один подшипник почти без смазки. Мы сняли крышку, тщательно очистили всё вокруг и заново смазали. В отчёте я написал не только, что мы сделали, но и предложил добавить дополнительные точки смазки в план технического обслуживания. Так я стараюсь думать и о сегодняшней остановке, и о том, как избежать следующей.	["B1", "work", "mechanic", "production-line", "duties", "repair", "bearing"]	t	2025-12-08 14:19:25.581861+00	2025-12-08 14:19:25.581879+00	På produksjonslinja der jeg jobber, er jeg ofte den første mekanikeren operatørene ringer til når noe skjer. Jeg kjenner maskinene godt, fordi jeg både gjør daglig vedlikehold og har vært med på flere større reparasjoner. En vanlig dag handler mye om små ting: skru fast løse deksler, bytte en slitt gummilist eller justere et bånd som går litt skeivt. Men noen ganger må vi stoppe hele linja for å finne en mer alvorlig feil. Forrige måned begynte en av drivstasjonene å lage høy, metallisk lyd. I stedet for å bare skru opp volumet på radioen, ba jeg operatøren stoppe linja. Sammen sjekket vi kjede, tannhjul og lager. Det viste seg at ett lager var nesten tørt for fett. Vi demonterte dekselet, renset området og smurte opp på nytt. I rapporten skrev jeg ikke bare hva vi hadde gjort, men også et forslag om å legge inn ekstra smørepunkter i vedlikeholdsplanen. Slik prøver jeg å tenke både på dagens stopp og på hvordan vi kan unngå det neste.	På produksjonslina der eg jobbar, er eg ofte den første mekanikaren operatørane ringer til når noko skjer. Eg kjenner maskinene godt, fordi eg både gjer dagleg vedlikehald og har vore med på fleire større reparasjonar. Ein vanleg dag handlar mykje om små ting: skru fast lause deksel, byte ei slitt gummilist eller justere eit band som går litt skeivt. Men nokre gonger må vi stoppe heile lina for å finne ein meir alvorleg feil. Førre månad begynte ein av drivstasjonane å lage høg, metallisk lyd. I staden for å berre skru opp volumet på radioen, bad eg operatøren stoppe lina. Sammen sjekka vi kjede, tannhjul og lager. Det viste seg at eitt lager var nesten tomt for feitt. Vi demonterte dekselet, reinsa området og smurte opp på nytt. I rapporten skreiv eg ikkje berre kva vi hadde gjort, men òg eit forslag om å leggje inn ekstra smørepunkter i vedlikehaldsplanen. Slik prøver eg å tenkje både på dagens stopp og på korleis vi kan unngå det neste.	On the production line where I work, I am often the first mechanic the operators call when something happens. I know the machines well, because I do daily maintenance and have taken part in several larger repairs. A normal day is often about small things: tightening loose covers, changing a worn rubber strip or adjusting a belt that runs a bit crooked. But sometimes we have to stop the whole line to find a more serious fault. Last month one of the drive stations started to make a loud metallic noise. Instead of just turning up the volume on the radio, I asked the operator to stop the line. Together we checked chain, gears and bearings. It turned out that one bearing was almost dry of grease. We removed the cover, cleaned the area and lubricated again. In the report I wrote not only what we had done, but also a suggestion to add extra lubrication points in the maintenance plan. In this way I try to think both about today’s stop and about how we can avoid the next one.	Role on the production line	Rolle på produksjonslinja	Rolle på produksjonslina	Роль на производственной линии
199	Ansvar og tryggleik på linja	b2-bm-line-mechanic-duties	bokmaal	B2	Som mekaniker på ei moderne produksjonsline er eg ikkje berre «han med verktøykassa», men ein del av eit større system. Eg har ansvar for at maskinene går, men òg for at dei som jobbar rundt, kan kjenne seg trygge. Kvar gong eg planlegg ein reparasjon, må eg tenkje på både produksjonsmål og sikkerheit: Kan vi ta denne jobben i ein kort stopp mellom to batchar, eller må vi avtale ein lengre stans med leiinga? Kva for låse- og merkingsrutinar må vere på plass før nokon får gå inn i maskina? Nyleg hadde vi ein jobb der vi måtte bytte fleire lager på ei høgdeløfta driv­eining. I staden for å «bare få det gjort», bad vi om tid til ei grundig stans: vi sperra av området, gjekk gjennom risikovurderinga og fordelte oppgåver i laget. Under demonteringa viste det seg at ei gamal provisorisk løysing nesten hadde blitt gløymd i dokumentasjonen. Vi tok bilete, oppdaterte teikningane og skreiv eit avvik. For meg er det ein viktig del av jobben å sørgje for at neste mekanikar som kjem til same maskin, møter ein litt tryggare og betre dokumentert arbeidsplass enn den eg møtte første gong.	Как механик на современной производственной линии, я не просто «человек с инструментами», а часть большой системы. Я отвечаю за то, чтобы оборудование работало, но и за то, чтобы люди вокруг него чувствовали себя в безопасности. Каждый раз, планируя ремонт, я должен думать и о производственных целях, и о безопасности: можем ли мы сделать эту работу в короткий останов между двумя партиями или нужно договариваться с руководством о более длинной остановке? Какие процедуры по блокировке и маркировке должны быть выполнены, прежде чем кто‑то полезет внутрь машины? Недавно у нас была задача заменить несколько подшипников на приподнятом приводном узле. Вместо того чтобы «просто сделать и забыть», мы попросили время на нормальный останов: огородили зону, прошли оценку рисков и распределили задачи внутри бригады. Во время разборки оказалось, что старая временная «заплатка» почти не была описана в документации. Мы сделали фотографии, обновили чертежи и оформили avvik — сообщение об отклонении. Для меня важная часть работы — сделать так, чтобы следующий механик, который придёт к этой же машине, попал на чуть более безопасное и лучше документированное рабочее место, чем то, которое застал я в первый раз.	["B2", "work", "mechanic", "production-line", "responsibility", "safety", "maintenance"]	t	2025-12-08 14:19:25.587894+00	2025-12-08 14:19:25.587913+00	Som mekaniker på ei moderne produksjonsline er eg ikkje berre «han med verktøykassa», men ein del av eit større system. Eg har ansvar for at maskinene går, men òg for at dei som jobbar rundt, kan kjenne seg trygge. Kvar gong eg planlegg ein reparasjon, må eg tenkje på både produksjonsmål og sikkerheit: Kan vi ta denne jobben i ein kort stopp mellom to batchar, eller må vi avtale ein lengre stans med leiinga? Kva for låse- og merkingsrutinar må vere på plass før nokon får gå inn i maskina? Nyleg hadde vi ein jobb der vi måtte bytte fleire lager på ei høgdeløfta driv­eining. I staden for å «bare få det gjort», bad vi om tid til ei grundig stans: vi sperra av området, gjekk gjennom risikovurderinga og fordelte oppgåver i laget. Under demonteringa viste det seg at ei gamal provisorisk løysing nesten hadde blitt gløymd i dokumentasjonen. Vi tok bilete, oppdaterte teikningane og skreiv eit avvik. For meg er det ein viktig del av jobben å sørgje for at neste mekanikar som kjem til same maskin, møter ein litt tryggare og betre dokumentert arbeidsplass enn den eg møtte første gong.	Som mekanikar på ei moderne produksjonsline er eg ikkje berre «han med verktøykassa», men ein del av eit større system. Eg har ansvar for at maskinene går, men òg for at dei som jobbar rundt, kan kjenne seg trygge. Kvar gong eg planlegg ein reparasjon, må eg tenkje på både produksjonsmål og tryggleik: Kan vi ta denne jobben i ein kort stopp mellom to batchar, eller må vi avtale ein lengre stans med leiinga? Kva for låse- og merkingsrutinar må vere på plass før nokon får gå inn i maskina? Nyleg hadde vi ein jobb der vi måtte byte fleire lager på ei høgdeløfta driveining. I staden for å «berre få det gjort», bad vi om tid til ei grundig stans: vi sperra av området, gjekk gjennom risikovurderinga og fordelte oppgåver i laget. Under demonteringa viste det seg at ei gammal provisorisk løysing nesten hadde blitt gløymd i dokumentasjonen. Vi tok bilete, oppdaterte teikningane og skreiv eit avvik. For meg er det ein viktig del av jobben å sørgje for at neste mekanikar som kjem til same maskin, møter ein litt tryggare og betre dokumentert arbeidsplass enn den eg møtte første gong.	As a mechanic on a modern production line I am not only “the one with the toolbox”, but part of a larger system. I am responsible for keeping the machines running, but also for making sure that the people around them can feel safe. Every time I plan a repair, I have to think about both production targets and safety: Can we do this job in a short stop between two batches, or do we need to agree on a longer shut-down with the management? Which lockout and tagging routines must be in place before anyone is allowed to go inside the machine? Recently we had a job where we had to change several bearings on an elevated drive unit. Instead of “just getting it done”, we asked for time for a proper stop: we closed off the area, went through the risk assessment and divided the tasks in the team. During the dismantling we discovered that an old temporary solution had almost been forgotten in the documentation. We took photos, updated the drawings and wrote a deviation report. For me an important part of the job is to make sure that the next mechanic who comes to the same machine meets a slightly safer and better documented workplace than the one I met the first time.	Responsibility and safety on the line	Ansvar og tryggleik på linja	Ansvar og tryggleik på lina	Ответственность и безопасность на линии
